     contains

     !> SLASYF_RK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> SLASYF_RK is an auxiliary routine called by SSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_slasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: sevten = 17.0e+0_sp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(sp) :: absakk,alpha,colmax,d11,d12,d21,d22,stemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_slamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = zero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_scopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_sgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_isamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_scopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_scopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_scopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_sgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_isamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_isamax(imax - 1,w(1,kw - 1),1)
                          stemp = abs(w(itemp,kw - 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_scopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_scopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_scopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_scopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_sswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_sswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_scopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_scopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_sswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_sswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_scopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_sscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = zero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_sgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_sgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = zero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_scopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_sgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_isamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_scopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_scopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_scopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_sgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_isamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_isamax(n - imax,w(imax + 1,k + 1),1)
                          stemp = abs(w(itemp,k + 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_scopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_scopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_scopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_scopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_sswap(k,a(k,1),lda,a(p,1),lda)
                    call la_sswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_scopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_scopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_sswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_sswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_scopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_sscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = zero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_sgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_sgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_slasyf_rk
     !> DLASYF_RK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> DLASYF_RK is an auxiliary routine called by DSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_dlasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(dp),parameter :: sevten = 17.0e+0_dp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(dp) :: absakk,alpha,colmax,d11,d12,d21,d22,dtemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_dlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = zero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_dcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_dgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_idamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_dcopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_dcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_dcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_dgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_idamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_idamax(imax - 1,w(1,kw - 1),1)
                          dtemp = abs(w(itemp,kw - 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_dcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_dcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_dcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_dcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_dswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_dswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_dcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_dcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_dswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_dswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_dcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_dscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = zero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_dgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_dgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = zero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_dcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_dgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_idamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_dcopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_dcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_dcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_dgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_idamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_idamax(n - imax,w(imax + 1,k + 1),1)
                          dtemp = abs(w(itemp,k + 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_dcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_dcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_dcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_dcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_dswap(k,a(k,1),lda,a(p,1),lda)
                    call la_dswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_dcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_dcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_dswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_dswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_dcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_dscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = zero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_dgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_dgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_dlasyf_rk
#ifdef LA_WITH_XDP
     !> XLASYF_RK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> XLASYF_RK is an auxiliary routine called by XSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_xlasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(xdp),parameter :: sevten = 17.0e+0_xdp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(xdp) :: absakk,alpha,colmax,d11,d12,d21,d22,xtemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_xlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = zero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_xcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_xgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_ixamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_xcopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_xcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_xcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_xgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_ixamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_ixamax(imax - 1,w(1,kw - 1),1)
                          xtemp = abs(w(itemp,kw - 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_xcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_xcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_xcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_xcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_xswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_xswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_xcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_xcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_xswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_xswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_xcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_xscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = zero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_xgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_xgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = zero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_xcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_xgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_ixamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_xcopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_xcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_xcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_xgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_ixamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_ixamax(n - imax,w(imax + 1,k + 1),1)
                          xtemp = abs(w(itemp,k + 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_xcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_xcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_xcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_xcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_xswap(k,a(k,1),lda,a(p,1),lda)
                    call la_xswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_xcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_xcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_xswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_xswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_xcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_xscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = zero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_xgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_xgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_xlasyf_rk
#endif
#ifdef LA_WITH_QP
     !> QLASYF_RK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> QLASYF_RK is an auxiliary routine called by QSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_qlasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: sevten = 17.0e+0_qp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(qp) :: absakk,alpha,colmax,d11,d12,d21,d22,qtemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_qlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = zero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_qcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_qgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iqamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_qcopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_qcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_qcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_qgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iqamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iqamax(imax - 1,w(1,kw - 1),1)
                          qtemp = abs(w(itemp,kw - 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_qcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_qcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_qcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_qcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_qswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_qswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_qcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_qcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_qswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_qswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_qcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_qscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = zero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_qgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_qgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = zero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_qcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_qgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iqamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_qcopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = zero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_qcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_qcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_qgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iqamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iqamax(n - imax,w(imax + 1,k + 1),1)
                          qtemp = abs(w(itemp,k + 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_qcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_qcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_qcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_qcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_qswap(k,a(k,1),lda,a(p,1),lda)
                    call la_qswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_qcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_qcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_qswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_qswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_qcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_qscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = zero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = zero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = zero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_qgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_qgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_qlasyf_rk
#endif

     !> SLASYF_ROOK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> SLASYF_ROOK is an auxiliary routine called by SSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_slasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: sevten = 17.0e+0_sp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(sp) :: absakk,alpha,colmax,d11,d12,d21,d22,stemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_slamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_scopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_sgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_isamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_scopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_scopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_scopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_sgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_isamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_isamax(imax - 1,w(1,kw - 1),1)
                          stemp = abs(w(itemp,kw - 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_scopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_scopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_scopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_scopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_sswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_sswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_scopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_scopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_sswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_sswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_scopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_sscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_sgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_sgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_sswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_sswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_scopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_sgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_isamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_scopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_scopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_scopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_sgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_isamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_isamax(n - imax,w(imax + 1,k + 1),1)
                          stemp = abs(w(itemp,k + 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_scopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_scopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_scopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_scopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_sswap(k,a(k,1),lda,a(p,1),lda)
                    call la_sswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_scopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_scopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_sswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_sswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_scopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_sscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_sgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_sgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_sswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_sswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_slasyf_rook
     !> DLASYF_ROOK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> DLASYF_ROOK is an auxiliary routine called by DSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_dlasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(dp),parameter :: sevten = 17.0e+0_dp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(dp) :: absakk,alpha,colmax,d11,d12,d21,d22,dtemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_dlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_dcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_dgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_idamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_dcopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_dcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_dcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_dgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_idamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_idamax(imax - 1,w(1,kw - 1),1)
                          dtemp = abs(w(itemp,kw - 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_dcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_dcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_dcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_dcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_dswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_dswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_dcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_dcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_dswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_dswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_dcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_dscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_dgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_dgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_dswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_dswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_dcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_dgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_idamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_dcopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_dcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_dcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_dgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_idamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_idamax(n - imax,w(imax + 1,k + 1),1)
                          dtemp = abs(w(itemp,k + 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_dcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_dcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_dcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_dcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_dswap(k,a(k,1),lda,a(p,1),lda)
                    call la_dswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_dcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_dcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_dswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_dswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_dcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_dscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_dgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_dgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_dswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_dswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_dlasyf_rook
#ifdef LA_WITH_XDP
     !> XLASYF_ROOK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> XLASYF_ROOK is an auxiliary routine called by XSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_xlasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(xdp),parameter :: sevten = 17.0e+0_xdp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(xdp) :: absakk,alpha,colmax,d11,d12,d21,d22,xtemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_xlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_xcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_xgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_ixamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_xcopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_xcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_xcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_xgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_ixamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_ixamax(imax - 1,w(1,kw - 1),1)
                          xtemp = abs(w(itemp,kw - 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_xcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_xcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_xcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_xcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_xswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_xswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_xcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_xcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_xswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_xswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_xcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_xscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_xgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_xgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_xswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_xswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_xcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_xgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_ixamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_xcopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_xcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_xcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_xgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_ixamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_ixamax(n - imax,w(imax + 1,k + 1),1)
                          xtemp = abs(w(itemp,k + 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_xcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_xcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_xcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_xcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_xswap(k,a(k,1),lda,a(p,1),lda)
                    call la_xswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_xcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_xcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_xswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_xswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_xcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_xscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_xgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_xgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_xswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_xswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_xlasyf_rook
#endif
#ifdef LA_WITH_QP
     !> QLASYF_ROOK: computes a partial factorization of a real symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> QLASYF_ROOK is an auxiliary routine called by QSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_qlasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: sevten = 17.0e+0_qp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(qp) :: absakk,alpha,colmax,d11,d12,d21,d22,qtemp,r1,rowmax,t, &
                     sfmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_qlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_qcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_qgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda,w(k,kw + &
                        1),ldw,one,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iqamax(k - 1,w(1,kw),1)
                 colmax = abs(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_qcopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_qcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_qcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_qgemv('NO TRANSPOSE',k,n - k,-one,a(1,k + 1),lda, &
                                 w(imax,kw + 1),ldw,one,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iqamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = abs(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iqamax(imax - 1,w(1,kw - 1),1)
                          qtemp = abs(w(itemp,kw - 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_qcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_qcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_qcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_qcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_qswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_qswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_qcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_qcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_qswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_qswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_qcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_qscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = one/(d11*d22 - one)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_qgemv('NO TRANSPOSE',jj - j + 1,n - k,-one,a(j,k + 1),lda,w(jj, &
                              kw + 1),ldw,one,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_qgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-one,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,one,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_qswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_qswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_qcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_qgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1),lda,w(k, &
                        1),ldw,one,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = abs(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iqamax(n - k,w(k + 1,k),1)
                 colmax = abs(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_qcopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_qcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_qcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_qgemv('NO TRANSPOSE',n - k + 1,k - 1,-one,a(k,1), &
                                 lda,w(imax,1),ldw,one,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iqamax(imax - k,w(k,k + 1),1)
                          rowmax = abs(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iqamax(n - imax,w(imax + 1,k + 1),1)
                          qtemp = abs(w(itemp,k + 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! abs( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (abs(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_qcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_qcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_qcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_qcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_qswap(k,a(k,1),lda,a(p,1),lda)
                    call la_qswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_qcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_qcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_qswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_qswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_qcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (abs(a(k,k)) >= sfmin) then
                          r1 = one/a(k,k)
                          call la_qscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= zero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = one/(d11*d22 - one)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_qgemv('NO TRANSPOSE',j + jb - jj,k - 1,-one,a(jj,1),lda,w(jj, &
                              1),ldw,one,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_qgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           one,a(j + jb,1),lda,w(j,1),ldw,one,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_qswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_qswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_qlasyf_rook
#endif

     !> SSPTRI: computes the inverse of a real symmetric indefinite matrix
     !> A in packed storage using the factorization A = U*D*U**T or
     !> A = L*D*L**T computed by SSPTRF.

     pure subroutine la_ssptri(uplo,n,ap,ipiv,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(inout) :: ap(*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,k,kc,kcnext,kp,kpc,kstep,kx,npp
           real(sp) :: ak,akkp1,akp1,d,t,temp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('SSPTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              kp = n*(n + 1)/2
              do info = n,1,-1
                 if (ipiv(info) > 0 .and. ap(kp) == zero) return
                 kp = kp - info
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              kp = 1
              do info = 1,n
                 if (ipiv(info) > 0 .and. ap(kp) == zero) return
                 kp = kp + n - info + 1
              end do
           end if
           info = 0
           if (upper) then
              ! compute inv(a) from the factorization a = u*d*u**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              kc = 1
              30 continue
              ! if k > n, exit from loop.
              if (k > n) go to 50
              kcnext = kc + k
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 ap(kc + k - 1) = one/ap(kc + k - 1)
                 ! compute column k of the inverse.
                 if (k > 1) then
                    call la_scopy(k - 1,ap(kc),1,work,1)
                    call la_sspmv(uplo,k - 1,-one,ap,work,1,zero,ap(kc),1)
                    ap(kc + k - 1) = ap(kc + k - 1) - la_sdot(k - 1,work,1,ap(kc),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(ap(kcnext + k - 1))
                 ak = ap(kc + k - 1)/t
                 akp1 = ap(kcnext + k)/t
                 akkp1 = ap(kcnext + k - 1)/t
                 d = t*(ak*akp1 - one)
                 ap(kc + k - 1) = akp1/d
                 ap(kcnext + k) = ak/d
                 ap(kcnext + k - 1) = -akkp1/d
                 ! compute columns k and k+1 of the inverse.
                 if (k > 1) then
                    call la_scopy(k - 1,ap(kc),1,work,1)
                    call la_sspmv(uplo,k - 1,-one,ap,work,1,zero,ap(kc),1)
                    ap(kc + k - 1) = ap(kc + k - 1) - la_sdot(k - 1,work,1,ap(kc),1)
                    ap(kcnext + k - 1) = ap(kcnext + k - 1) - la_sdot(k - 1,ap(kc),1,ap( &
                              kcnext),1)
                    call la_scopy(k - 1,ap(kcnext),1,work,1)
                    call la_sspmv(uplo,k - 1,-one,ap,work,1,zero,ap(kcnext),1)

                    ap(kcnext + k) = ap(kcnext + k) - la_sdot(k - 1,work,1,ap(kcnext),1)

                 end if
                 kstep = 2
                 kcnext = kcnext + k + 1
              end if
              kp = abs(ipiv(k))
              if (kp /= k) then
                 ! interchange rows and columns k and kp in the leading
                 ! submatrix a(1:k+1,1:k+1)
                 kpc = (kp - 1)*kp/2 + 1
                 call la_sswap(kp - 1,ap(kc),1,ap(kpc),1)
                 kx = kpc + kp - 1
                 do j = kp + 1,k - 1
                    kx = kx + j - 1
                    temp = ap(kc + j - 1)
                    ap(kc + j - 1) = ap(kx)
                    ap(kx) = temp
                 end do
                 temp = ap(kc + k - 1)
                 ap(kc + k - 1) = ap(kpc + kp - 1)
                 ap(kpc + kp - 1) = temp
                 if (kstep == 2) then
                    temp = ap(kc + k + k - 1)
                    ap(kc + k + k - 1) = ap(kc + k + kp - 1)
                    ap(kc + k + kp - 1) = temp
                 end if
              end if
              k = k + kstep
              kc = kcnext
              go to 30
              50 continue
           else
              ! compute inv(a) from the factorization a = l*d*l**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              npp = n*(n + 1)/2
              k = n
              kc = npp
              60 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 80
              kcnext = kc - (n - k + 2)
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 ap(kc) = one/ap(kc)
                 ! compute column k of the inverse.
                 if (k < n) then
                    call la_scopy(n - k,ap(kc + 1),1,work,1)
                    call la_sspmv(uplo,n - k,-one,ap(kc + n - k + 1),work,1,zero,ap(kc + 1), &
                              1)
                    ap(kc) = ap(kc) - la_sdot(n - k,work,1,ap(kc + 1),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(ap(kcnext + 1))
                 ak = ap(kcnext)/t
                 akp1 = ap(kc)/t
                 akkp1 = ap(kcnext + 1)/t
                 d = t*(ak*akp1 - one)
                 ap(kcnext) = akp1/d
                 ap(kc) = ak/d
                 ap(kcnext + 1) = -akkp1/d
                 ! compute columns k-1 and k of the inverse.
                 if (k < n) then
                    call la_scopy(n - k,ap(kc + 1),1,work,1)
                    call la_sspmv(uplo,n - k,-one,ap(kc + (n - k + 1)),work,1,zero,ap(kc + &
                              1),1)
                    ap(kc) = ap(kc) - la_sdot(n - k,work,1,ap(kc + 1),1)
                    ap(kcnext + 1) = ap(kcnext + 1) - la_sdot(n - k,ap(kc + 1),1,ap(kcnext + 2 &
                              ),1)
                    call la_scopy(n - k,ap(kcnext + 2),1,work,1)
                    call la_sspmv(uplo,n - k,-one,ap(kc + (n - k + 1)),work,1,zero,ap( &
                              kcnext + 2),1)
                    ap(kcnext) = ap(kcnext) - la_sdot(n - k,work,1,ap(kcnext + 2),1)

                 end if
                 kstep = 2
                 kcnext = kcnext - (n - k + 3)
              end if
              kp = abs(ipiv(k))
              if (kp /= k) then
                 ! interchange rows and columns k and kp in the trailing
                 ! submatrix a(k-1:n,k-1:n)
                 kpc = npp - (n - kp + 1)*(n - kp + 2)/2 + 1
                 if (kp < n) call la_sswap(n - kp,ap(kc + kp - k + 1),1,ap(kpc + 1),1)
                 kx = kc + kp - k
                 do j = k + 1,kp - 1
                    kx = kx + n - j + 1
                    temp = ap(kc + j - k)
                    ap(kc + j - k) = ap(kx)
                    ap(kx) = temp
                 end do
                 temp = ap(kc)
                 ap(kc) = ap(kpc)
                 ap(kpc) = temp
                 if (kstep == 2) then
                    temp = ap(kc - n + k - 1)
                    ap(kc - n + k - 1) = ap(kc - n + kp - 1)
                    ap(kc - n + kp - 1) = temp
                 end if
              end if
              k = k - kstep
              kc = kcnext
              go to 60
              80 continue
           end if
           return
     end subroutine la_ssptri
