              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 ap(kc) = one/ap(kc)
                 ! compute column k of the inverse.
                 if (k < n) then
                    call la_xcopy(n - k,ap(kc + 1),1,work,1)
                    call la_xspmv(uplo,n - k,-one,ap(kc + n - k + 1),work,1,zero,ap(kc + 1), &
                              1)
                    ap(kc) = ap(kc) - la_xdot(n - k,work,1,ap(kc + 1),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(ap(kcnext + 1))
                 ak = ap(kcnext)/t
                 akp1 = ap(kc)/t
                 akkp1 = ap(kcnext + 1)/t
                 d = t*(ak*akp1 - one)
                 ap(kcnext) = akp1/d
                 ap(kc) = ak/d
                 ap(kcnext + 1) = -akkp1/d
                 ! compute columns k-1 and k of the inverse.
                 if (k < n) then
                    call la_xcopy(n - k,ap(kc + 1),1,work,1)
                    call la_xspmv(uplo,n - k,-one,ap(kc + (n - k + 1)),work,1,zero,ap(kc + &
                              1),1)
                    ap(kc) = ap(kc) - la_xdot(n - k,work,1,ap(kc + 1),1)
                    ap(kcnext + 1) = ap(kcnext + 1) - la_xdot(n - k,ap(kc + 1),1,ap(kcnext + 2 &
                              ),1)
                    call la_xcopy(n - k,ap(kcnext + 2),1,work,1)
                    call la_xspmv(uplo,n - k,-one,ap(kc + (n - k + 1)),work,1,zero,ap( &
                              kcnext + 2),1)
                    ap(kcnext) = ap(kcnext) - la_xdot(n - k,work,1,ap(kcnext + 2),1)

                 end if
                 kstep = 2
                 kcnext = kcnext - (n - k + 3)
              end if
              kp = abs(ipiv(k))
              if (kp /= k) then
                 ! interchange rows and columns k and kp in the trailing
                 ! submatrix a(k-1:n,k-1:n)
                 kpc = npp - (n - kp + 1)*(n - kp + 2)/2 + 1
                 if (kp < n) call la_xswap(n - kp,ap(kc + kp - k + 1),1,ap(kpc + 1),1)
                 kx = kc + kp - k
                 do j = k + 1,kp - 1
                    kx = kx + n - j + 1
                    temp = ap(kc + j - k)
                    ap(kc + j - k) = ap(kx)
                    ap(kx) = temp
                 end do
                 temp = ap(kc)
                 ap(kc) = ap(kpc)
                 ap(kpc) = temp
                 if (kstep == 2) then
                    temp = ap(kc - n + k - 1)
                    ap(kc - n + k - 1) = ap(kc - n + kp - 1)
                    ap(kc - n + kp - 1) = temp
                 end if
              end if
              k = k - kstep
              kc = kcnext
              go to 60
              80 continue
           end if
           return
     end subroutine la_xsptri
#endif
#ifdef LA_WITH_QP
     !> QSPTRI: computes the inverse of a real symmetric indefinite matrix
     !> A in packed storage using the factorization A = U*D*U**T or
     !> A = L*D*L**T computed by QSPTRF.

     pure subroutine la_qsptri(uplo,n,ap,ipiv,work,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(qp),intent(inout) :: ap(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,k,kc,kcnext,kp,kpc,kstep,kx,npp
           real(qp) :: ak,akkp1,akp1,d,t,temp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('QSPTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              kp = n*(n + 1)/2
              do info = n,1,-1
                 if (ipiv(info) > 0 .and. ap(kp) == zero) return
                 kp = kp - info
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              kp = 1
              do info = 1,n
                 if (ipiv(info) > 0 .and. ap(kp) == zero) return
                 kp = kp + n - info + 1
              end do
           end if
           info = 0
           if (upper) then
              ! compute inv(a) from the factorization a = u*d*u**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              kc = 1
              30 continue
              ! if k > n, exit from loop.
              if (k > n) go to 50
              kcnext = kc + k
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 ap(kc + k - 1) = one/ap(kc + k - 1)
                 ! compute column k of the inverse.
                 if (k > 1) then
                    call la_qcopy(k - 1,ap(kc),1,work,1)
                    call la_qspmv(uplo,k - 1,-one,ap,work,1,zero,ap(kc),1)
                    ap(kc + k - 1) = ap(kc + k - 1) - la_qdot(k - 1,work,1,ap(kc),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(ap(kcnext + k - 1))
                 ak = ap(kc + k - 1)/t
                 akp1 = ap(kcnext + k)/t
                 akkp1 = ap(kcnext + k - 1)/t
                 d = t*(ak*akp1 - one)
                 ap(kc + k - 1) = akp1/d
                 ap(kcnext + k) = ak/d
                 ap(kcnext + k - 1) = -akkp1/d
                 ! compute columns k and k+1 of the inverse.
                 if (k > 1) then
                    call la_qcopy(k - 1,ap(kc),1,work,1)
                    call la_qspmv(uplo,k - 1,-one,ap,work,1,zero,ap(kc),1)
                    ap(kc + k - 1) = ap(kc + k - 1) - la_qdot(k - 1,work,1,ap(kc),1)
                    ap(kcnext + k - 1) = ap(kcnext + k - 1) - la_qdot(k - 1,ap(kc),1,ap( &
                              kcnext),1)
                    call la_qcopy(k - 1,ap(kcnext),1,work,1)
                    call la_qspmv(uplo,k - 1,-one,ap,work,1,zero,ap(kcnext),1)

                    ap(kcnext + k) = ap(kcnext + k) - la_qdot(k - 1,work,1,ap(kcnext),1)

                 end if
                 kstep = 2
                 kcnext = kcnext + k + 1
              end if
              kp = abs(ipiv(k))
              if (kp /= k) then
                 ! interchange rows and columns k and kp in the leading
                 ! submatrix a(1:k+1,1:k+1)
                 kpc = (kp - 1)*kp/2 + 1
                 call la_qswap(kp - 1,ap(kc),1,ap(kpc),1)
                 kx = kpc + kp - 1
                 do j = kp + 1,k - 1
                    kx = kx + j - 1
                    temp = ap(kc + j - 1)
                    ap(kc + j - 1) = ap(kx)
                    ap(kx) = temp
                 end do
                 temp = ap(kc + k - 1)
                 ap(kc + k - 1) = ap(kpc + kp - 1)
                 ap(kpc + kp - 1) = temp
                 if (kstep == 2) then
                    temp = ap(kc + k + k - 1)
                    ap(kc + k + k - 1) = ap(kc + k + kp - 1)
                    ap(kc + k + kp - 1) = temp
                 end if
              end if
              k = k + kstep
              kc = kcnext
              go to 30
              50 continue
           else
              ! compute inv(a) from the factorization a = l*d*l**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              npp = n*(n + 1)/2
              k = n
              kc = npp
              60 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 80
              kcnext = kc - (n - k + 2)
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 ap(kc) = one/ap(kc)
                 ! compute column k of the inverse.
                 if (k < n) then
                    call la_qcopy(n - k,ap(kc + 1),1,work,1)
                    call la_qspmv(uplo,n - k,-one,ap(kc + n - k + 1),work,1,zero,ap(kc + 1), &
                              1)
                    ap(kc) = ap(kc) - la_qdot(n - k,work,1,ap(kc + 1),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(ap(kcnext + 1))
                 ak = ap(kcnext)/t
                 akp1 = ap(kc)/t
                 akkp1 = ap(kcnext + 1)/t
                 d = t*(ak*akp1 - one)
                 ap(kcnext) = akp1/d
                 ap(kc) = ak/d
                 ap(kcnext + 1) = -akkp1/d
                 ! compute columns k-1 and k of the inverse.
                 if (k < n) then
                    call la_qcopy(n - k,ap(kc + 1),1,work,1)
                    call la_qspmv(uplo,n - k,-one,ap(kc + (n - k + 1)),work,1,zero,ap(kc + &
                              1),1)
                    ap(kc) = ap(kc) - la_qdot(n - k,work,1,ap(kc + 1),1)
                    ap(kcnext + 1) = ap(kcnext + 1) - la_qdot(n - k,ap(kc + 1),1,ap(kcnext + 2 &
                              ),1)
                    call la_qcopy(n - k,ap(kcnext + 2),1,work,1)
                    call la_qspmv(uplo,n - k,-one,ap(kc + (n - k + 1)),work,1,zero,ap( &
                              kcnext + 2),1)
                    ap(kcnext) = ap(kcnext) - la_qdot(n - k,work,1,ap(kcnext + 2),1)

                 end if
                 kstep = 2
                 kcnext = kcnext - (n - k + 3)
              end if
              kp = abs(ipiv(k))
              if (kp /= k) then
                 ! interchange rows and columns k and kp in the trailing
                 ! submatrix a(k-1:n,k-1:n)
                 kpc = npp - (n - kp + 1)*(n - kp + 2)/2 + 1
                 if (kp < n) call la_qswap(n - kp,ap(kc + kp - k + 1),1,ap(kpc + 1),1)
                 kx = kc + kp - k
                 do j = k + 1,kp - 1
                    kx = kx + n - j + 1
                    temp = ap(kc + j - k)
                    ap(kc + j - k) = ap(kx)
                    ap(kx) = temp
                 end do
                 temp = ap(kc)
                 ap(kc) = ap(kpc)
                 ap(kpc) = temp
                 if (kstep == 2) then
                    temp = ap(kc - n + k - 1)
                    ap(kc - n + k - 1) = ap(kc - n + kp - 1)
                    ap(kc - n + kp - 1) = temp
                 end if
              end if
              k = k - kstep
              kc = kcnext
              go to 60
              80 continue
           end if
           return
     end subroutine la_qsptri
#endif

     !> SSPTRS: solves a system of linear equations A*X = B with a real
     !> symmetric matrix A stored in packed format using the factorization
     !> A = U*D*U**T or A = L*D*L**T computed by SSPTRF.

     pure subroutine la_ssptrs(uplo,n,nrhs,ap,ipiv,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(sp),intent(in) :: ap(*)
           real(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,k,kc,kp
           real(sp) :: ak,akm1,akm1k,bk,bkm1,denom
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('SSPTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b, where a = u*d*u**t.
              ! first solve u*d*x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              kc = n*(n + 1)/2 + 1
              10 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 30
              kc = kc - k
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_sswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(u(k)), where u(k) is the transformation
                 ! stored in column k of a.
                 call la_sger(k - 1,nrhs,-one,ap(kc),1,b(k,1),ldb,b(1,1),ldb)

                 ! multiply by the inverse of the diagonal block.
                 call la_sscal(nrhs,one/ap(kc + k - 1),b(k,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k-1 and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k - 1) call la_sswap(nrhs,b(k - 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(u(k)), where u(k) is the transformation
                 ! stored in columns k-1 and k of a.
                 call la_sger(k - 2,nrhs,-one,ap(kc),1,b(k,1),ldb,b(1,1),ldb)

                 call la_sger(k - 2,nrhs,-one,ap(kc - (k - 1)),1,b(k - 1,1),ldb,b(1,1 &
                           ),ldb)
                 ! multiply by the inverse of the diagonal block.
                 akm1k = ap(kc + k - 2)
                 akm1 = ap(kc - 1)/akm1k
                 ak = ap(kc + k - 1)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k - 1,j)/akm1k
                    bk = b(k,j)/akm1k
                    b(k - 1,j) = (ak*bkm1 - bk)/denom
                    b(k,j) = (akm1*bk - bkm1)/denom
                 end do
                 kc = kc - k + 1
                 k = k - 2
              end if
              go to 10
              30 continue
              ! next solve u**t*x = b, overwriting b with x.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              kc = 1
              40 continue
              ! if k > n, exit from loop.
              if (k > n) go to 50
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(u**t(k)), where u(k) is the transformation
                 ! stored in column k of a.
                 call la_sgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,ap(kc),1,one,b(k, &
                           1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_sswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc + k
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(u**t(k+1)), where u(k+1) is the transformation
                 ! stored in columns k and k+1 of a.
                 call la_sgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,ap(kc),1,one,b(k, &
                           1),ldb)
                 call la_sgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,ap(kc + k),1,one,b(k + &
                           1,1),ldb)
                 ! interchange rows k and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k) call la_sswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc + 2*k + 1
                 k = k + 2
              end if
              go to 40
              50 continue
           else
              ! solve a*x = b, where a = l*d*l**t.
              ! first solve l*d*x = b, overwriting b with x.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              kc = 1
              60 continue
              ! if k > n, exit from loop.
              if (k > n) go to 80
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_sswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_sger(n - k,nrhs,-one,ap(kc + 1),1,b(k,1),ldb,b(k + 1, &
                            1),ldb)
                 ! multiply by the inverse of the diagonal block.
                 call la_sscal(nrhs,one/ap(kc),b(k,1),ldb)
                 kc = kc + n - k + 1
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k+1 and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k + 1) call la_sswap(nrhs,b(k + 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in columns k and k+1 of a.
                 if (k < n - 1) then
                    call la_sger(n - k - 1,nrhs,-one,ap(kc + 2),1,b(k,1),ldb,b(k + 2,1) &
                              ,ldb)
                    call la_sger(n - k - 1,nrhs,-one,ap(kc + n - k + 2),1,b(k + 1,1),ldb,b(k + &
                              2,1),ldb)
                 end if
                 ! multiply by the inverse of the diagonal block.
                 akm1k = ap(kc + 1)
                 akm1 = ap(kc)/akm1k
                 ak = ap(kc + n - k + 1)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k,j)/akm1k
                    bk = b(k + 1,j)/akm1k
                    b(k,j) = (ak*bkm1 - bk)/denom
                    b(k + 1,j) = (akm1*bk - bkm1)/denom
                 end do
                 kc = kc + 2*(n - k) + 1
                 k = k + 2
              end if
              go to 60
              80 continue
              ! next solve l**t*x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              kc = n*(n + 1)/2 + 1
              90 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 100
              kc = kc - (n - k + 1)
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(l**t(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_sgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,ap( &
                           kc + 1),1,one,b(k,1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_sswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(l**t(k-1)), where l(k-1) is the transformation
                 ! stored in columns k-1 and k of a.
                 if (k < n) then
                    call la_sgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,ap(kc + 1), &
                              1,one,b(k,1),ldb)
                    call la_sgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,ap(kc - (n - &
                              k)),1,one,b(k - 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k) call la_sswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc - (n - k + 2)
                 k = k - 2
              end if
              go to 90
              100 continue
           end if
           return
     end subroutine la_ssptrs
     !> DSPTRS: solves a system of linear equations A*X = B with a real
     !> symmetric matrix A stored in packed format using the factorization
     !> A = U*D*U**T or A = L*D*L**T computed by DSPTRF.

     pure subroutine la_dsptrs(uplo,n,nrhs,ap,ipiv,b,ldb,info)
        use la_constants_dp
        ! -- lapack computational routine --
