              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(u(k)), where u(k) is the transformation
                 ! stored in column k of a.
                 call la_dger(k - 1,nrhs,-one,ap(kc),1,b(k,1),ldb,b(1,1),ldb)

                 ! multiply by the inverse of the diagonal block.
                 call la_dscal(nrhs,one/ap(kc + k - 1),b(k,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k-1 and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k - 1) call la_dswap(nrhs,b(k - 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(u(k)), where u(k) is the transformation
                 ! stored in columns k-1 and k of a.
                 call la_dger(k - 2,nrhs,-one,ap(kc),1,b(k,1),ldb,b(1,1),ldb)

                 call la_dger(k - 2,nrhs,-one,ap(kc - (k - 1)),1,b(k - 1,1),ldb,b(1,1 &
                           ),ldb)
                 ! multiply by the inverse of the diagonal block.
                 akm1k = ap(kc + k - 2)
                 akm1 = ap(kc - 1)/akm1k
                 ak = ap(kc + k - 1)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k - 1,j)/akm1k
                    bk = b(k,j)/akm1k
                    b(k - 1,j) = (ak*bkm1 - bk)/denom
                    b(k,j) = (akm1*bk - bkm1)/denom
                 end do
                 kc = kc - k + 1
                 k = k - 2
              end if
              go to 10
              30 continue
              ! next solve u**t*x = b, overwriting b with x.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              kc = 1
              40 continue
              ! if k > n, exit from loop.
              if (k > n) go to 50
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(u**t(k)), where u(k) is the transformation
                 ! stored in column k of a.
                 call la_dgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,ap(kc),1,one,b(k, &
                           1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc + k
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(u**t(k+1)), where u(k+1) is the transformation
                 ! stored in columns k and k+1 of a.
                 call la_dgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,ap(kc),1,one,b(k, &
                           1),ldb)
                 call la_dgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,ap(kc + k),1,one,b(k + &
                           1,1),ldb)
                 ! interchange rows k and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc + 2*k + 1
                 k = k + 2
              end if
              go to 40
              50 continue
           else
              ! solve a*x = b, where a = l*d*l**t.
              ! first solve l*d*x = b, overwriting b with x.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              kc = 1
              60 continue
              ! if k > n, exit from loop.
              if (k > n) go to 80
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_dger(n - k,nrhs,-one,ap(kc + 1),1,b(k,1),ldb,b(k + 1, &
                            1),ldb)
                 ! multiply by the inverse of the diagonal block.
                 call la_dscal(nrhs,one/ap(kc),b(k,1),ldb)
                 kc = kc + n - k + 1
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k+1 and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k + 1) call la_dswap(nrhs,b(k + 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in columns k and k+1 of a.
                 if (k < n - 1) then
                    call la_dger(n - k - 1,nrhs,-one,ap(kc + 2),1,b(k,1),ldb,b(k + 2,1) &
                              ,ldb)
                    call la_dger(n - k - 1,nrhs,-one,ap(kc + n - k + 2),1,b(k + 1,1),ldb,b(k + &
                              2,1),ldb)
                 end if
                 ! multiply by the inverse of the diagonal block.
                 akm1k = ap(kc + 1)
                 akm1 = ap(kc)/akm1k
                 ak = ap(kc + n - k + 1)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k,j)/akm1k
                    bk = b(k + 1,j)/akm1k
                    b(k,j) = (ak*bkm1 - bk)/denom
                    b(k + 1,j) = (akm1*bk - bkm1)/denom
                 end do
                 kc = kc + 2*(n - k) + 1
                 k = k + 2
              end if
              go to 60
              80 continue
              ! next solve l**t*x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              kc = n*(n + 1)/2 + 1
              90 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 100
              kc = kc - (n - k + 1)
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(l**t(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_dgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,ap( &
                           kc + 1),1,one,b(k,1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(l**t(k-1)), where l(k-1) is the transformation
                 ! stored in columns k-1 and k of a.
                 if (k < n) then
                    call la_dgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,ap(kc + 1), &
                              1,one,b(k,1),ldb)
                    call la_dgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,ap(kc - (n - &
                              k)),1,one,b(k - 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc - (n - k + 2)
                 k = k - 2
              end if
              go to 90
              100 continue
           end if
           return
     end subroutine la_dsptrs
