              if (k > n) go to 35
              if (k <= n - nb) then
                 ! factorize columns k:k+kb-1 of a and use blocked code to
                 ! update columns k+kb:n
                 call la_dlasyf_rk(uplo,n - k + 1,nb,kb,a(k,k),lda,e(k),ipiv(k), &
