                 ! -ipiv(k-1) in the trailing submatrix a(k-1:n,k-1:n)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_dswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_dswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k - 1)
                    a(k,k - 1) = a(kp,k - 1)
                    a(kp,k - 1) = temp
                 end if
                 k = k - 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_dswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_dswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k - 1
              go to 50
              60 continue
           end if
           return
     end subroutine la_dsytri_rook
#ifdef LA_WITH_XDP
     !> XSYTRI_ROOK: computes the inverse of a real symmetric
     !> matrix A using the factorization A = U*D*U**T or A = L*D*L**T
     !> computed by XSYTRF_ROOK.

     pure subroutine la_xsytri_rook(uplo,n,a,lda,ipiv,work,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: k,kp,kstep
           real(xdp) :: ak,akkp1,akp1,d,t,temp
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('XSYTRI_ROOK',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              do info = n,1,-1
                 if (ipiv(info) > 0 .and. a(info,info) == zero) return
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              do info = 1,n
                 if (ipiv(info) > 0 .and. a(info,info) == zero) return
              end do
           end if
           info = 0
           if (upper) then
              ! compute inv(a) from the factorization a = u*d*u**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              30 continue
              ! if k > n, exit from loop.
              if (k > n) go to 40
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 a(k,k) = one/a(k,k)
                 ! compute column k of the inverse.
                 if (k > 1) then
                    call la_xcopy(k - 1,a(1,k),1,work,1)
                    call la_xsymv(uplo,k - 1,-one,a,lda,work,1,zero,a(1,k),1)

                    a(k,k) = a(k,k) - la_xdot(k - 1,work,1,a(1,k),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(a(k,k + 1))
                 ak = a(k,k)/t
                 akp1 = a(k + 1,k + 1)/t
                 akkp1 = a(k,k + 1)/t
                 d = t*(ak*akp1 - one)
                 a(k,k) = akp1/d
                 a(k + 1,k + 1) = ak/d
                 a(k,k + 1) = -akkp1/d
                 ! compute columns k and k+1 of the inverse.
                 if (k > 1) then
                    call la_xcopy(k - 1,a(1,k),1,work,1)
                    call la_xsymv(uplo,k - 1,-one,a,lda,work,1,zero,a(1,k),1)

                    a(k,k) = a(k,k) - la_xdot(k - 1,work,1,a(1,k),1)
                    a(k,k + 1) = a(k,k + 1) - la_xdot(k - 1,a(1,k),1,a(1,k + 1),1)

                    call la_xcopy(k - 1,a(1,k + 1),1,work,1)
                    call la_xsymv(uplo,k - 1,-one,a,lda,work,1,zero,a(1,k + 1),1)

                    a(k + 1,k + 1) = a(k + 1,k + 1) - la_xdot(k - 1,work,1,a(1,k + 1),1)

                 end if
                 kstep = 2
              end if
              if (kstep == 1) then
                 ! interchange rows and columns k and ipiv(k) in the leading
                 ! submatrix a(1:k+1,1:k+1)
                 kp = ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_xswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_xswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              else
                 ! interchange rows and columns k and k+1 with -ipiv(k) and
                 ! -ipiv(k+1)in the leading submatrix a(1:k+1,1:k+1)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_xswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_xswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k + 1)
                    a(k,k + 1) = a(kp,k + 1)
                    a(kp,k + 1) = temp
                 end if
                 k = k + 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_xswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_xswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k + 1
              go to 30
              40 continue
           else
              ! compute inv(a) from the factorization a = l*d*l**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              50 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 60
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 a(k,k) = one/a(k,k)
                 ! compute column k of the inverse.
                 if (k < n) then
                    call la_xcopy(n - k,a(k + 1,k),1,work,1)
                    call la_xsymv(uplo,n - k,-one,a(k + 1,k + 1),lda,work,1,zero,a(k + 1, &
                              k),1)
                    a(k,k) = a(k,k) - la_xdot(n - k,work,1,a(k + 1,k),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = abs(a(k,k - 1))
                 ak = a(k - 1,k - 1)/t
                 akp1 = a(k,k)/t
                 akkp1 = a(k,k - 1)/t
                 d = t*(ak*akp1 - one)
                 a(k - 1,k - 1) = akp1/d
                 a(k,k) = ak/d
                 a(k,k - 1) = -akkp1/d
                 ! compute columns k-1 and k of the inverse.
                 if (k < n) then
                    call la_xcopy(n - k,a(k + 1,k),1,work,1)
                    call la_xsymv(uplo,n - k,-one,a(k + 1,k + 1),lda,work,1,zero,a(k + 1, &
                              k),1)
                    a(k,k) = a(k,k) - la_xdot(n - k,work,1,a(k + 1,k),1)
                    a(k,k - 1) = a(k,k - 1) - la_xdot(n - k,a(k + 1,k),1,a(k + 1,k - 1),1)

                    call la_xcopy(n - k,a(k + 1,k - 1),1,work,1)
                    call la_xsymv(uplo,n - k,-one,a(k + 1,k + 1),lda,work,1,zero,a(k + 1, &
                              k - 1),1)
                    a(k - 1,k - 1) = a(k - 1,k - 1) - la_xdot(n - k,work,1,a(k + 1,k - 1),1)

                 end if
                 kstep = 2
              end if
              if (kstep == 1) then
                 ! interchange rows and columns k and ipiv(k) in the trailing
                 ! submatrix a(k-1:n,k-1:n)
                 kp = ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_xswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_xswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              else
                 ! interchange rows and columns k and k-1 with -ipiv(k) and
                 ! -ipiv(k-1) in the trailing submatrix a(k-1:n,k-1:n)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_xswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_xswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k - 1)
                    a(k,k - 1) = a(kp,k - 1)
                    a(kp,k - 1) = temp
                 end if
                 k = k - 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_xswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_xswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k - 1
              go to 50
              60 continue
           end if
           return
     end subroutine la_xsytri_rook
