           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(dp),intent(in) :: a(lda,*)
           real(dp),intent(inout) :: b(ldb,*)
           real(dp),intent(out) :: work(*)
        ! =====================================================================

           logical(lk) :: lquery,upper
           integer(ilp) :: k,kp,lwkopt
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           info = 0
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -8
           else if (lwork < max(1,3*n - 2) .and. .not. lquery) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('DSYTRS_AA',-info)
              return
           else if (lquery) then
              lwkopt = (3*n - 2)
              work(1) = lwkopt
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b, where a = u**t*t*u.
              ! 1) forward substitution with u**t
              if (n > 1) then
                 ! pivot, p**t * b -> b
                 do k = 1,n
                    kp = ipiv(k)
                    if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 end do
                 ! compute u**t \ b -> b    [ (u**t \p**t * b) ]
                 call la_dtrsm('L','U','T','U',n - 1,nrhs,one,a(1,2),lda,b(2,1), &
                           ldb)
              end if
              ! 2) solve with triangular matrix t
              ! compute t \ b -> b   [ t \ (u**t \p**t * b) ]
              call la_dlacpy('F',1,n,a(1,1),lda + 1,work(n),1)
              if (n > 1) then
                 call la_dlacpy('F',1,n - 1,a(1,2),lda + 1,work(1),1)
                 call la_dlacpy('F',1,n - 1,a(1,2),lda + 1,work(2*n),1)
              end if
              call la_dgtsv(n,nrhs,work(1),work(n),work(2*n),b,ldb,info)
              ! 3) backward substitution with u
              if (n > 1) then
                 ! compute u \ b -> b   [ u \ (t \ (u**t \p**t * b) ) ]
                 call la_dtrsm('L','U','N','U',n - 1,nrhs,one,a(1,2),lda,b(2,1), &
                           ldb)
                 ! pivot, p * b -> b  [ p * (u \ (t \ (u**t \p**t * b) )) ]
                 do k = n,1,-1
                    kp = ipiv(k)
                    if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 end do
              end if
           else
              ! solve a*x = b, where a = l*t*l**t.
              ! 1) forward substitution with l
              if (n > 1) then
                 ! pivot, p**t * b -> b
                 do k = 1,n
                    kp = ipiv(k)
                    if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 end do
                 ! compute l \ b -> b    [ (l \p**t * b) ]
                 call la_dtrsm('L','L','N','U',n - 1,nrhs,one,a(2,1),lda,b(2,1), &
                           ldb)
              end if
              ! 2) solve with triangular matrix t
              ! compute t \ b -> b   [ t \ (l \p**t * b) ]
              call la_dlacpy('F',1,n,a(1,1),lda + 1,work(n),1)
              if (n > 1) then
                 call la_dlacpy('F',1,n - 1,a(2,1),lda + 1,work(1),1)
                 call la_dlacpy('F',1,n - 1,a(2,1),lda + 1,work(2*n),1)
              end if
              call la_dgtsv(n,nrhs,work(1),work(n),work(2*n),b,ldb,info)
              ! 3) backward substitution with l**t
              if (n > 1) then
                 ! compute (l**t \ b) -> b   [ l**t \ (t \ (l \p**t * b) ) ]
                 call la_dtrsm('L','L','T','U',n - 1,nrhs,one,a(2,1),lda,b(2,1), &
                           ldb)
                 ! pivot, p * b -> b  [ p * (l**t \ (t \ (l \p**t * b) )) ]
                 do k = n,1,-1
                    kp = ipiv(k)
                    if (kp /= k) call la_dswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 end do
              end if
           end if
           return
