                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_xger(n - k,nrhs,-one,a(k + 1,k),1,b(k,1),ldb,b(k + &
                           1,1),ldb)
                 ! multiply by the inverse of the diagonal block.
                 call la_xscal(nrhs,one/a(k,k),b(k,1),ldb)
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k and -ipiv(k) then k+1 and -ipiv(k+1)
                 kp = -ipiv(k)
                 if (kp /= k) call la_xswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k + 1)
                 if (kp /= k + 1) call la_xswap(nrhs,b(k + 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in columns k and k+1 of a.
                 if (k < n - 1) then
                    call la_xger(n - k - 1,nrhs,-one,a(k + 2,k),1,b(k,1),ldb,b(k + 2,1 &
                              ),ldb)
                    call la_xger(n - k - 1,nrhs,-one,a(k + 2,k + 1),1,b(k + 1,1),ldb,b(k + &
                              2,1),ldb)
                 end if
                 ! multiply by the inverse of the diagonal block.
                 akm1k = a(k + 1,k)
                 akm1 = a(k,k)/akm1k
                 ak = a(k + 1,k + 1)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k,j)/akm1k
                    bk = b(k + 1,j)/akm1k
                    b(k,j) = (ak*bkm1 - bk)/denom
                    b(k + 1,j) = (akm1*bk - bkm1)/denom
                 end do
                 k = k + 2
              end if
              go to 60
              80 continue
              ! next solve l**t *x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              90 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 100
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(l**t(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_xgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,a(k + &
                           1,k),1,one,b(k,1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_xswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(l**t(k-1)), where l(k-1) is the transformation
                 ! stored in columns k-1 and k of a.
                 if (k < n) then
                    call la_xgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,a(k + 1,k), &
                               1,one,b(k,1),ldb)
                    call la_xgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,a(k + 1,k - 1 &
                              ),1,one,b(k - 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k) then k-1 and -ipiv(k-1)
                 kp = -ipiv(k)
                 if (kp /= k) call la_xswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k - 1)
                 if (kp /= k - 1) call la_xswap(nrhs,b(k - 1,1),ldb,b(kp,1),ldb)
                 k = k - 2
              end if
              go to 90
              100 continue
           end if
           return
     end subroutine la_xsytrs_rook
#endif
#ifdef LA_WITH_QP
     !> QSYTRS_ROOK: solves a system of linear equations A*X = B with
     !> a real symmetric matrix A using the factorization A = U*D*U**T or
     !> A = L*D*L**T computed by QSYTRF_ROOK.

     pure subroutine la_qsytrs_rook(uplo,n,nrhs,a,lda,ipiv,b,ldb,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           real(qp),intent(in) :: a(lda,*)
           real(qp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,k,kp
           real(qp) :: ak,akm1,akm1k,bk,bkm1,denom
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('QSYTRS_ROOK',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b, where a = u*d*u**t.
              ! first solve u*d*x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              10 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 30
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(u(k)), where u(k) is the transformation
                 ! stored in column k of a.
                 call la_qger(k - 1,nrhs,-one,a(1,k),1,b(k,1),ldb,b(1,1),ldb)

                 ! multiply by the inverse of the diagonal block.
                 call la_qscal(nrhs,one/a(k,k),b(k,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k and -ipiv(k) then k-1 and -ipiv(k-1)
                 kp = -ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k - 1)
                 if (kp /= k - 1) call la_qswap(nrhs,b(k - 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(u(k)), where u(k) is the transformation
                 ! stored in columns k-1 and k of a.
                 if (k > 2) then
                    call la_qger(k - 2,nrhs,-one,a(1,k),1,b(k,1),ldb,b(1,1), &
                              ldb)
                    call la_qger(k - 2,nrhs,-one,a(1,k - 1),1,b(k - 1,1),ldb,b(1,1), &
                               ldb)
                 end if
                 ! multiply by the inverse of the diagonal block.
                 akm1k = a(k - 1,k)
                 akm1 = a(k - 1,k - 1)/akm1k
                 ak = a(k,k)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k - 1,j)/akm1k
                    bk = b(k,j)/akm1k
                    b(k - 1,j) = (ak*bkm1 - bk)/denom
                    b(k,j) = (akm1*bk - bkm1)/denom
                 end do
                 k = k - 2
              end if
              go to 10
              30 continue
              ! next solve u**t *x = b, overwriting b with x.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              40 continue
              ! if k > n, exit from loop.
              if (k > n) go to 50
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(u**t(k)), where u(k) is the transformation
                 ! stored in column k of a.
                 if (k > 1) call la_qgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,a(1,k),1, &
                           one,b(k,1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(u**t(k+1)), where u(k+1) is the transformation
                 ! stored in columns k and k+1 of a.
                 if (k > 1) then
                    call la_qgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,a(1,k),1,one,b( &
                              k,1),ldb)
                    call la_qgemv('TRANSPOSE',k - 1,nrhs,-one,b,ldb,a(1,k + 1),1,one, &
                              b(k + 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k) then k+1 and -ipiv(k+1).
                 kp = -ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k + 1)
                 if (kp /= k + 1) call la_qswap(nrhs,b(k + 1,1),ldb,b(kp,1),ldb)
                 k = k + 2
              end if
              go to 40
              50 continue
           else
              ! solve a*x = b, where a = l*d*l**t.
              ! first solve l*d*x = b, overwriting b with x.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              60 continue
              ! if k > n, exit from loop.
              if (k > n) go to 80
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_qger(n - k,nrhs,-one,a(k + 1,k),1,b(k,1),ldb,b(k + &
                           1,1),ldb)
                 ! multiply by the inverse of the diagonal block.
                 call la_qscal(nrhs,one/a(k,k),b(k,1),ldb)
                 k = k + 1
              else
                 ! 2 x 2 diagonal block
                 ! interchange rows k and -ipiv(k) then k+1 and -ipiv(k+1)
                 kp = -ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k + 1)
                 if (kp /= k + 1) call la_qswap(nrhs,b(k + 1,1),ldb,b(kp,1),ldb)
                 ! multiply by inv(l(k)), where l(k) is the transformation
                 ! stored in columns k and k+1 of a.
                 if (k < n - 1) then
                    call la_qger(n - k - 1,nrhs,-one,a(k + 2,k),1,b(k,1),ldb,b(k + 2,1 &
                              ),ldb)
                    call la_qger(n - k - 1,nrhs,-one,a(k + 2,k + 1),1,b(k + 1,1),ldb,b(k + &
                              2,1),ldb)
                 end if
                 ! multiply by the inverse of the diagonal block.
                 akm1k = a(k + 1,k)
                 akm1 = a(k,k)/akm1k
                 ak = a(k + 1,k + 1)/akm1k
                 denom = akm1*ak - one
                 do j = 1,nrhs
                    bkm1 = b(k,j)/akm1k
                    bk = b(k + 1,j)/akm1k
                    b(k,j) = (ak*bkm1 - bk)/denom
                    b(k + 1,j) = (akm1*bk - bkm1)/denom
                 end do
                 k = k + 2
              end if
              go to 60
              80 continue
              ! next solve l**t *x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              90 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 100
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(l**t(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_qgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,a(k + &
                           1,k),1,one,b(k,1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(l**t(k-1)), where l(k-1) is the transformation
                 ! stored in columns k-1 and k of a.
                 if (k < n) then
                    call la_qgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,a(k + 1,k), &
                               1,one,b(k,1),ldb)
                    call la_qgemv('TRANSPOSE',n - k,nrhs,-one,b(k + 1,1),ldb,a(k + 1,k - 1 &
                              ),1,one,b(k - 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k) then k-1 and -ipiv(k-1)
                 kp = -ipiv(k)
                 if (kp /= k) call la_qswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k - 1)
                 if (kp /= k - 1) call la_qswap(nrhs,b(k - 1,1),ldb,b(kp,1),ldb)
                 k = k - 2
              end if
              go to 90
              100 continue
           end if
           return
     end subroutine la_qsytrs_rook
#endif

     !> SSPRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is symmetric indefinite
     !> and packed, and provides error bounds and backward error estimates
     !> for the solution.

     pure subroutine la_ssprfs(uplo,n,nrhs,ap,afp,ipiv,b,ldb,x,ldx,ferr,berr,work, &
                iwork,info)
        use la_constants_sp,only:zero,one,two,three
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: afp(*),ap(*),b(ldb,*)
           real(sp),intent(out) :: berr(*),ferr(*),work(*)
           real(sp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: count,i,ik,j,k,kase,kk,nz
           real(sp) :: eps,lstres,s,safe1,safe2,safmin,xk
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -8
           else if (ldx < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('SSPRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = n + 1
           eps = la_slamch('EPSILON')
           safmin = la_slamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_140: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - a * x
              call la_scopy(n,b(1,j),1,work(n + 1),1)
              call la_sspmv(uplo,n,-one,ap,x(1,j),1,one,work(n + 1),1)
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(a)*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              do i = 1,n
                 work(i) = abs(b(i,j))
              end do
              ! compute abs(a)*abs(x) + abs(b).
              kk = 1
              if (upper) then
                 do k = 1,n
                    s = zero
                    xk = abs(x(k,j))
                    ik = kk
                    do i = 1,k - 1
                       work(i) = work(i) + abs(ap(ik))*xk
                       s = s + abs(ap(ik))*abs(x(i,j))
                       ik = ik + 1
                    end do
                    work(k) = work(k) + abs(ap(kk + k - 1))*xk + s
                    kk = kk + k
                 end do
              else
                 do k = 1,n
                    s = zero
                    xk = abs(x(k,j))
                    work(k) = work(k) + abs(ap(kk))*xk
                    ik = kk + 1
                    do i = k + 1,n
                       work(i) = work(i) + abs(ap(ik))*xk
                       s = s + abs(ap(ik))*abs(x(i,j))
                       ik = ik + 1
                    end do
                    work(k) = work(k) + s
                    kk = kk + (n - k + 1)
                 end do
              end if
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_ssptrs(uplo,n,1,afp,ipiv,work(n + 1),n,info)
                 call la_saxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(a))*
                 ! ( abs(r) + nz*eps*( abs(a)*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(a) is the inverse of a
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(a)*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(a)*abs(x) + abs(b) is less than safe2.
              ! use la_slacn2 to estimate the infinity-norm of the matrix
                 ! inv(a) * diag(w),
              ! where w = abs(r) + nz*eps*( abs(a)*abs(x)+abs(b) )))
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              kase = 0
              100 continue
              call la_slacn2(n,work(2*n + 1),work(n + 1),iwork,ferr(j),kase,isave)

              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(a**t).
                    call la_ssptrs(uplo,n,1,afp,ipiv,work(n + 1),n,info)
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                 else if (kase == 2) then
                    ! multiply by inv(a)*diag(w).
                    do i = 1,n
                       work(n + i) = work(i)*work(n + i)
                    end do
                    call la_ssptrs(uplo,n,1,afp,ipiv,work(n + 1),n,info)
                 end if
                 go to 100
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_140
           return
     end subroutine la_ssprfs
     !> DSPRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is symmetric indefinite
     !> and packed, and provides error bounds and backward error estimates
     !> for the solution.

     pure subroutine la_dsprfs(uplo,n,nrhs,ap,afp,ipiv,b,ldb,x,ldx,ferr,berr,work, &
                iwork,info)
