     !> SSYCON_ROOK: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a real symmetric matrix A using the factorization
     !> A = U*D*U**T or A = L*D*L**T computed by SSYTRF_ROOK.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_ssycon_rook(uplo,n,a,lda,ipiv,anorm,rcond,work,iwork,info)
        use la_constants_sp

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: a(lda,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,kase
           real(sp) :: ainvnm
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SSYCON_ROOK',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm <= zero) then
              return
           end if
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              do i = n,1,-1
                 if (ipiv(i) > 0 .and. a(i,i) == zero) return
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              do i = 1,n
                 if (ipiv(i) > 0 .and. a(i,i) == zero) return
              end do
           end if
           ! estimate the 1-norm of the inverse.
           kase = 0
           30 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              ! multiply by inv(l*d*l**t) or inv(u*d*u**t).
              call la_ssytrs_rook(uplo,n,1,a,lda,ipiv,work,n,info)
              go to 30
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           return
     end subroutine la_ssycon_rook
     !> DSYCON_ROOK: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a real symmetric matrix A using the factorization
     !> A = U*D*U**T or A = L*D*L**T computed by DSYTRF_ROOK.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_dsycon_rook(uplo,n,a,lda,ipiv,anorm,rcond,work,iwork,info)
        use la_constants_dp

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(dp),intent(in) :: anorm
           real(dp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           integer(ilp),intent(out) :: iwork(*)
           real(dp),intent(in) :: a(lda,*)
           real(dp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,kase
           real(dp) :: ainvnm
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DSYCON_ROOK',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm <= zero) then
              return
           end if
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              do i = n,1,-1
                 if (ipiv(i) > 0 .and. a(i,i) == zero) return
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              do i = 1,n
                 if (ipiv(i) > 0 .and. a(i,i) == zero) return
              end do
           end if
           ! estimate the 1-norm of the inverse.
           kase = 0
           30 continue
           call la_dlacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              ! multiply by inv(l*d*l**t) or inv(u*d*u**t).
              call la_dsytrs_rook(uplo,n,1,a,lda,ipiv,work,n,info)
              go to 30
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           return
     end subroutine la_dsycon_rook
