           integer(ilp),intent(in) :: m,nb,j1,lda,ldh
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           real(xdp),intent(inout) :: a(lda,*),h(ldh,*)
           real(xdp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: j,k,k1,i1,i2,mj
           real(xdp) :: piv,alpha
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           j = 1
           ! k1 is the first column of the panel to be factorized
           ! i.e.,  k1 is 2 for the first block column, and 1 for the rest of the blocks
           k1 = (2 - j1) + 1
           if (la_lsame(uplo,'U')) then
              ! .....................................................
              ! factorize a as u**t*d*u using the upper triangle of a
              ! .....................................................
              10 continue
              if (j > min(m,nb)) go to 20
              ! k is the column to be factorized
               ! when being called from la_xsytrf_aa,
               ! > for the first block column, j1 is 1, hence j1+j-1 is j,
               ! > for the rest of the columns, j1 is 2, and j1+j-1 is j+1,
              k = j1 + j - 1
              if (j == m) then
                  ! only need to compute t(j, j)
                  mj = 1
              else
                  mj = m - j + 1
              end if
              ! h(j:m, j) := a(j, j:m) - h(j:m, 1:(j-1)) * l(j1:(j-1), j),
               ! where h(j:m, j) has been initialized to be a(j, j:m)
              if (k > 2) then
              ! k is the column to be factorized
               ! > for the first block column, k is j, skipping the first two
                 ! columns
               ! > for the rest of the columns, k is j+1, skipping only the
                 ! first column
                 call la_xgemv('NO TRANSPOSE',mj,j - k1,-one,h(j,k1),ldh,a(1,j),1, &
                           one,h(j,j),1)
              end if
              ! copy h(i:m, i) into work
              call la_xcopy(mj,h(j,j),1,work(1),1)
              if (j > k1) then
                 ! compute work := work - l(j-1, j:m) * t(j-1,j),
                  ! where a(j-1, j) stores t(j-1, j) and a(j-2, j:m) stores u(j-1, j:m)
                 alpha = -a(k - 1,j)
                 call la_xaxpy(mj,alpha,a(k - 2,j),lda,work(1),1)
              end if
              ! set a(j, j) = t(j, j)
              a(k,j) = work(1)
              if (j < m) then
                 ! compute work(2:m) = t(j, j) l(j, (j+1):m)
                  ! where a(j, j) stores t(j, j) and a(j-1, (j+1):m) stores u(j, (j+1):m)
                 if (k > 1) then
                    alpha = -a(k,j)
                    call la_xaxpy(m - j,alpha,a(k - 1,j + 1),lda,work(2),1)
                 end if
                 ! find max(|work(2:m)|)
                 i2 = la_ixamax(m - j,work(2),1) + 1
                 piv = work(i2)
                 ! apply symmetric pivot
                 if ((i2 /= 2) .and. (piv /= 0)) then
                    ! swap work(i1) and work(i2)
                    i1 = 2
                    work(i2) = work(i1)
                    work(i1) = piv
                    ! swap a(i1, i1+1:m) with a(i1+1:m, i2)
                    i1 = i1 + j - 1
                    i2 = i2 + j - 1
                    call la_xswap(i2 - i1 - 1,a(j1 + i1 - 1,i1 + 1),lda,a(j1 + i1,i2),1)

                    ! swap a(i1, i2+1:m) with a(i2, i2+1:m)
                    if (i2 < m) call la_xswap(m - i2,a(j1 + i1 - 1,i2 + 1),lda,a(j1 + i2 - 1,i2 + 1), &
                               lda)
                    ! swap a(i1, i1) with a(i2,i2)
                    piv = a(i1 + j1 - 1,i1)
                    a(j1 + i1 - 1,i1) = a(j1 + i2 - 1,i2)
                    a(j1 + i2 - 1,i2) = piv
                    ! swap h(i1, 1:j1) with h(i2, 1:j1)
                    call la_xswap(i1 - 1,h(i1,1),ldh,h(i2,1),ldh)
                    ipiv(i1) = i2
                    if (i1 > (k1 - 1)) then
                       ! swap l(1:i1-1, i1) with l(1:i1-1, i2),
                        ! skipping the first column
                       call la_xswap(i1 - k1 + 1,a(1,i1),1,a(1,i2),1)
                    end if
                 else
                    ipiv(j + 1) = j + 1
                 end if
                 ! set a(j, j+1) = t(j, j+1)
                 a(k,j + 1) = work(2)
                 if (j < nb) then
                    ! copy a(j+1:m, j+1) into h(j:m, j),
                    call la_xcopy(m - j,a(k + 1,j + 1),lda,h(j + 1,j + 1),1)
                 end if
                 ! compute l(j+2, j+1) = work( 3:m ) / t(j, j+1),
                  ! where a(j, j+1) = t(j, j+1) and a(j+2:m, j) = l(j+2:m, j+1)
                 if (j < (m - 1)) then
                    if (a(k,j + 1) /= zero) then
                       alpha = one/a(k,j + 1)
                       call la_xcopy(m - j - 1,work(3),1,a(k,j + 2),lda)
                       call la_xscal(m - j - 1,alpha,a(k,j + 2),lda)
                    else
                       call la_xlaset('FULL',1,m - j - 1,zero,zero,a(k,j + 2),lda)
                    end if
                 end if
              end if
              j = j + 1
              go to 10
              20 continue
           else
              ! .....................................................
              ! factorize a as l*d*l**t using the lower triangle of a
              ! .....................................................
              30 continue
              if (j > min(m,nb)) go to 40
              ! k is the column to be factorized
               ! when being called from la_xsytrf_aa,
               ! > for the first block column, j1 is 1, hence j1+j-1 is j,
               ! > for the rest of the columns, j1 is 2, and j1+j-1 is j+1,
              k = j1 + j - 1
              if (j == m) then
                  ! only need to compute t(j, j)
                  mj = 1
              else
                  mj = m - j + 1
              end if
              ! h(j:m, j) := a(j:m, j) - h(j:m, 1:(j-1)) * l(j, j1:(j-1))^t,
               ! where h(j:m, j) has been initialized to be a(j:m, j)
              if (k > 2) then
              ! k is the column to be factorized
               ! > for the first block column, k is j, skipping the first two
                 ! columns
               ! > for the rest of the columns, k is j+1, skipping only the
                 ! first column
                 call la_xgemv('NO TRANSPOSE',mj,j - k1,-one,h(j,k1),ldh,a(j,1),lda, &
                           one,h(j,j),1)
              end if
              ! copy h(j:m, j) into work
              call la_xcopy(mj,h(j,j),1,work(1),1)
              if (j > k1) then
                 ! compute work := work - l(j:m, j-1) * t(j-1,j),
                  ! where a(j-1, j) = t(j-1, j) and a(j, j-2) = l(j, j-1)
                 alpha = -a(j,k - 1)
                 call la_xaxpy(mj,alpha,a(j,k - 2),1,work(1),1)
              end if
              ! set a(j, j) = t(j, j)
              a(j,k) = work(1)
              if (j < m) then
                 ! compute work(2:m) = t(j, j) l((j+1):m, j)
                  ! where a(j, j) = t(j, j) and a((j+1):m, j-1) = l((j+1):m, j)
                 if (k > 1) then
                    alpha = -a(j,k)
                    call la_xaxpy(m - j,alpha,a(j + 1,k - 1),1,work(2),1)
                 end if
                 ! find max(|work(2:m)|)
                 i2 = la_ixamax(m - j,work(2),1) + 1
                 piv = work(i2)
                 ! apply symmetric pivot
                 if ((i2 /= 2) .and. (piv /= 0)) then
                    ! swap work(i1) and work(i2)
                    i1 = 2
                    work(i2) = work(i1)
                    work(i1) = piv
                    ! swap a(i1+1:m, i1) with a(i2, i1+1:m)
                    i1 = i1 + j - 1
                    i2 = i2 + j - 1
                    call la_xswap(i2 - i1 - 1,a(i1 + 1,j1 + i1 - 1),1,a(i2,j1 + i1),lda)

