                       j3 = j2
                       do mj = nj - 1,1,-1
                          call la_dgemv('NO TRANSPOSE',mj,jb + 1,-one,work(j3 - j1 + 1 + k1*n), &
                                    n,a(j3,j1 - k2),lda,one,a(j3,j3),1)
                          j3 = j3 + 1
                       end do
                       ! update off-diagonal block in j2-th block column with la_dgemm
                       call la_dgemm('NO TRANSPOSE','TRANSPOSE',n - j3 + 1,nj,jb + 1,-one,work( &
                                  j3 - j1 + 1 + k1*n),n,a(j2,j1 - k2),lda,one,a(j3,j2),lda)
