                    a(j + 1,j) = alpha
                 end if
                 ! work(j+1, 1) stores h(j+1, 1)
                 call la_dcopy(n - j,a(j + 1,j + 1),1,work(1),1)
              end if
              go to 11
           end if
           20 continue
           work(1) = lwkopt
           return
