                       j3 = j2
                       do mj = nj - 1,1,-1
                          call la_qgemv('NO TRANSPOSE',mj,jb + 1,-one,work(j3 - j1 + 1 + k1*n), &
                                    n,a(j3,j1 - k2),lda,one,a(j3,j3),1)
                          j3 = j3 + 1
                       end do
                       ! update off-diagonal block in j2-th block column with la_qgemm
                       call la_qgemm('NO TRANSPOSE','TRANSPOSE',n - j3 + 1,nj,jb + 1,-one,work( &
                                  j3 - j1 + 1 + k1*n),n,a(j2,j1 - k2),lda,one,a(j3,j2),lda)
                    end do
                    ! recover t( j+1, j )
                    a(j + 1,j) = alpha
                 end if
                 ! work(j+1, 1) stores h(j+1, 1)
                 call la_qcopy(n - j,a(j + 1,j + 1),1,work(1),1)
              end if
              go to 11
           end if
           20 continue
           work(1) = lwkopt
           return
     end subroutine la_qsytrf_aa
#endif

     !> CLASYF_RK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> CLASYF_RK is an auxiliary routine called by CSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_clasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: sevten = 17.0e+0_sp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(sp) :: absakk,alpha,colmax,rowmax,sfmin,stemp
           complex(sp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,aimag,max,min,real,sqrt
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=sp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_slamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_ccopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_cgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_icamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ccopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_ccopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_ccopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_cgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_icamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_icamax(imax - 1,w(1,kw - 1),1)
                          stemp = cabs1(w(itemp,kw - 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_ccopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ccopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ccopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_ccopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_cswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_cswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ccopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_ccopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_cswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_cswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_ccopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_cscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = czero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_cgemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_cgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_ccopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_cgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_icamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ccopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_ccopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_ccopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_cgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_icamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_icamax(n - imax,w(imax + 1,k + 1),1)
                          stemp = cabs1(w(itemp,k + 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_ccopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ccopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ccopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_ccopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_cswap(k,a(k,1),lda,a(p,1),lda)
                    call la_cswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ccopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_ccopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_cswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_cswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_ccopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_cscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = czero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_cgemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_cgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_clasyf_rk
     !> ZLASYF_RK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> ZLASYF_RK is an auxiliary routine called by ZSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_zlasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(dp),parameter :: sevten = 17.0e+0_dp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(dp) :: absakk,alpha,colmax,rowmax,sfmin,dtemp
           complex(dp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,real,aimag,max,min,sqrt
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=dp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_dlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_zcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_zgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_izamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_zcopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_zcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_zcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_zgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_izamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_izamax(imax - 1,w(1,kw - 1),1)
                          dtemp = cabs1(w(itemp,kw - 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_zcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_zcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_zcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_zcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_zswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_zswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_zcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_zcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_zswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_zswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_zcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_zscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = czero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_zgemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_zgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_zcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_zgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_izamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_zcopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_zcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_zcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_zgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_izamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_izamax(n - imax,w(imax + 1,k + 1),1)
                          dtemp = cabs1(w(itemp,k + 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_zcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_zcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_zcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_zcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_zswap(k,a(k,1),lda,a(p,1),lda)
                    call la_zswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_zcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_zcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_zswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_zswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_zcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_zscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = czero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_zgemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_zgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_zlasyf_rk
#ifdef LA_WITH_XDP
     !> YLASYF_RK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> YLASYF_RK is an auxiliary routine called by YSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_ylasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(xdp),parameter :: sevten = 17.0e+0_xdp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(xdp) :: absakk,alpha,colmax,rowmax,sfmin,xtemp
           complex(xdp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,real,aimag,max,min,sqrt
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=xdp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_xlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_ycopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_ygemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iyamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ycopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_ycopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_ycopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_ygemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iyamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iyamax(imax - 1,w(1,kw - 1),1)
                          xtemp = cabs1(w(itemp,kw - 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_ycopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ycopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ycopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_ycopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_yswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_yswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ycopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_ycopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_yswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_yswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_ycopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_yscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = czero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_ygemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_ygemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_ycopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_ygemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iyamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ycopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_ycopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_ycopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_ygemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iyamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iyamax(n - imax,w(imax + 1,k + 1),1)
                          xtemp = cabs1(w(itemp,k + 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_ycopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ycopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ycopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_ycopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_yswap(k,a(k,1),lda,a(p,1),lda)
                    call la_yswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ycopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_ycopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_yswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_yswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_ycopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_yscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = czero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_ygemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_ygemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_ylasyf_rk
#endif
#ifdef LA_WITH_QP
     !> WLASYF_RK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman (rook) diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L',
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> WLASYF_RK is an auxiliary routine called by WSYTRF_RK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_wlasyf_rk(uplo,n,nb,kb,a,lda,e,ipiv,w,ldw,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: e(*),w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: sevten = 17.0e+0_qp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,k,kk,kw,kkw,kp,kstep,p,ii
           real(qp) :: absakk,alpha,colmax,rowmax,sfmin,qtemp
           complex(qp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,real,aimag,max,min,sqrt
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=qp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_qlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_wcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_wgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iwamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_wcopy(k,w(1,kw),1,a(1,k),1)
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_wcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_wcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_wgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iwamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iwamax(imax - 1,w(1,kw - 1),1)
                          qtemp = cabs1(w(itemp,kw - 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_wcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_wcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_wcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_wcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_wswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_wswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_wcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_wcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_wswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_wswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_wcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_wscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy superdiagonal element of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = czero
                    a(k,k) = w(k,kw)
                    e(k) = w(k - 1,kw)
                    e(k - 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_wgemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_wgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_wcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_wgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iwamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_wcopy(n - k + 1,w(k,k),1,a(k,k),1)
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_wcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_wcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_wgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iwamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iwamax(n - imax,w(imax + 1,k + 1),1)
                          qtemp = cabs1(w(itemp,k + 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_wcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_wcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_wcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_wcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_wswap(k,a(k,1),lda,a(p,1),lda)
                    call la_wswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_wcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_wcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_wswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_wswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_wcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_wscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy diagonal elements of d(k) to a,
                    ! copy subdiagonal element of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = czero
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                    e(k) = w(k + 1,k)
                    e(k + 1) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_wgemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_wgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_wlasyf_rk
#endif

     !> CLASYF_ROOK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> CLASYF_ROOK is an auxiliary routine called by CSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_clasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: sevten = 17.0e+0_sp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(sp) :: absakk,alpha,colmax,rowmax,stemp,sfmin
           complex(sp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt,aimag,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=sp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_slamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_ccopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_cgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_icamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ccopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_ccopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_ccopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_cgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_icamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_icamax(imax - 1,w(1,kw - 1),1)
                          stemp = cabs1(w(itemp,kw - 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_ccopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ccopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ccopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_ccopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_cswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_cswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ccopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_ccopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_cswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_cswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_ccopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_cscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_cgemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_cgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_cswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_cswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_ccopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_cgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_icamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ccopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_ccopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_ccopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_cgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_icamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_icamax(n - imax,w(imax + 1,k + 1),1)
                          stemp = cabs1(w(itemp,k + 1))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_ccopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ccopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ccopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_ccopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_cswap(k,a(k,1),lda,a(p,1),lda)
                    call la_cswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ccopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_ccopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_cswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_cswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_ccopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_cscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_cgemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_cgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_cswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_cswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_clasyf_rook
     !> ZLASYF_ROOK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> ZLASYF_ROOK is an auxiliary routine called by ZSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_zlasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(dp),parameter :: sevten = 17.0e+0_dp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(dp) :: absakk,alpha,colmax,rowmax,dtemp,sfmin
           complex(dp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt,aimag,real
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=dp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_dlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_zcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_zgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_izamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_zcopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_zcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_zcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_zgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_izamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_izamax(imax - 1,w(1,kw - 1),1)
                          dtemp = cabs1(w(itemp,kw - 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_zcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_zcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_zcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_zcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_zswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_zswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_zcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_zcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_zswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_zswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_zcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_zscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_zgemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_zgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_zswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_zswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_zcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_zgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_izamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_zcopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_zcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_zcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_zgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_izamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_izamax(n - imax,w(imax + 1,k + 1),1)
                          dtemp = cabs1(w(itemp,k + 1))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_zcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_zcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_zcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_zcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_zswap(k,a(k,1),lda,a(p,1),lda)
                    call la_zswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_zcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_zcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_zswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_zswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_zcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_zscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_zgemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_zgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_zswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_zswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_zlasyf_rook
#ifdef LA_WITH_XDP
     !> YLASYF_ROOK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> YLASYF_ROOK is an auxiliary routine called by YSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_ylasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(xdp),parameter :: sevten = 17.0e+0_xdp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(xdp) :: absakk,alpha,colmax,rowmax,xtemp,sfmin
           complex(xdp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt,aimag,real
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=xdp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_xlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_ycopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_ygemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iyamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ycopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_ycopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_ycopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_ygemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iyamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iyamax(imax - 1,w(1,kw - 1),1)
                          xtemp = cabs1(w(itemp,kw - 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_ycopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ycopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ycopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_ycopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_yswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_yswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ycopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_ycopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_yswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_yswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_ycopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_yscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_ygemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_ygemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_yswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_yswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_ycopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_ygemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iyamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_ycopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_ycopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_ycopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_ygemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iyamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iyamax(n - imax,w(imax + 1,k + 1),1)
                          xtemp = cabs1(w(itemp,k + 1))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_ycopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_ycopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_ycopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_ycopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_yswap(k,a(k,1),lda,a(p,1),lda)
                    call la_yswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_ycopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_ycopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_yswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_yswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_ycopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_yscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_ygemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_ygemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_yswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_yswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_ylasyf_rook
#endif
#ifdef LA_WITH_QP
     !> WLASYF_ROOK: computes a partial factorization of a complex symmetric
     !> matrix A using the bounded Bunch-Kaufman ("rook") diagonal
     !> pivoting method. The partial factorization has the form:
     !> A  =  ( I  U12 ) ( A11  0  ) (  I       0    )  if UPLO = 'U', or:
     !> ( 0  U22 ) (  0   D  ) ( U12**T U22**T )
     !> A  =  ( L11  0 ) (  D   0  ) ( L11**T L21**T )  if UPLO = 'L'
     !> ( L21  I ) (  0  A22 ) (  0       I    )
     !> where the order of D is at most NB. The actual order is returned in
     !> the argument KB, and is either NB or NB-1, or N if N <= NB.
     !> WLASYF_ROOK is an auxiliary routine called by WSYTRF_ROOK. It uses
     !> blocked code (calling Level 3 BLAS) to update the submatrix
     !> A11 (if UPLO = 'U') or A22 (if UPLO = 'L').

     pure subroutine la_wlasyf_rook(uplo,n,nb,kb,a,lda,ipiv,w,ldw,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,kb
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: w(ldw,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: sevten = 17.0e+0_qp

           ! Local Scalars
           logical(lk) :: done
           integer(ilp) :: imax,itemp,j,jb,jj,jmax,jp1,jp2,k,kk,kw,kkw,kp,kstep,p, &
                     ii
           real(qp) :: absakk,alpha,colmax,rowmax,qtemp,sfmin
           complex(qp) :: d11,d12,d21,d22,r1,t,z
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt,aimag,real
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=qp)) + abs(aimag(z))
           ! Executable Statements
           info = 0
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_qlamch('S')
           if (la_lsame(uplo,'U')) then
              ! factorize the trailing columns of a using the upper triangle
              ! of a and working backwards, and compute the matrix w = u12*d
              ! for use in updating a11
              ! k is the main loop index, decreasing from n in steps of 1 or 2
              k = n
              10 continue
              ! kw is the column of w which corresponds to column k of a
              kw = nb + k - n
              ! exit from loop
              if ((k <= n - nb + 1 .and. nb < n) .or. k < 1) go to 30
              kstep = 1
              p = k
              ! copy column k of a to column kw of w and update it
              call la_wcopy(k,a(1,k),1,w(1,kw),1)
              if (k < n) call la_wgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda,w(k, &
                        kw + 1),ldw,cone,w(1,kw),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,kw))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iwamax(k - 1,w(1,kw),1)
                 colmax = cabs1(w(imax,kw))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_wcopy(k,w(1,kw),1,a(1,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! copy column imax to column kw-1 of w and update it
                       call la_wcopy(imax,a(1,imax),1,w(1,kw - 1),1)
                       call la_wcopy(k - imax,a(imax,imax + 1),lda,w(imax + 1,kw - 1),1)

                       if (k < n) call la_wgemv('NO TRANSPOSE',k,n - k,-cone,a(1,k + 1),lda, &
                                  w(imax,kw + 1),ldw,cone,w(1,kw - 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iwamax(k - imax,w(imax + 1,kw - 1),1)
                          rowmax = cabs1(w(jmax,kw - 1))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iwamax(imax - 1,w(1,kw - 1),1)
                          qtemp = cabs1(w(itemp,kw - 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, kw-1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,kw - 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column kw-1 of w to column kw of w
                          call la_wcopy(k,w(1,kw - 1),1,w(1,kw),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k-1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_wcopy(k,w(1,kw - 1),1,w(1,kw),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! ============================================================
                 kk = k - kstep + 1
                 ! kkw is the column of w which corresponds to column kk of a
                 kkw = nb + kk - n
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_wcopy(k - p,a(p + 1,k),1,a(p,p + 1),lda)
                    call la_wcopy(p,a(1,k),1,a(1,p),1)
                    ! interchange rows k and p in last n-k+1 columns of a
                    ! and last n-k+2 columns of w
                    call la_wswap(n - k + 1,a(k,k),lda,a(p,k),lda)
                    call la_wswap(n - kk + 1,w(k,kkw),ldw,w(p,kkw),ldw)
                 end if
                 ! updated column kp is already stored in column kkw of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_wcopy(k - 1 - kp,a(kp + 1,kk),1,a(kp,kp + 1),lda)
                    call la_wcopy(kp,a(1,kk),1,a(1,kp),1)
                    ! interchange rows kk and kp in last n-kk+1 columns
                    ! of a and w
                    call la_wswap(n - kk + 1,a(kk,kk),lda,a(kp,kk),lda)
                    call la_wswap(n - kk + 1,w(kk,kkw),ldw,w(kp,kkw),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column kw of w now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    ! store u(k) in column k of a
                    call la_wcopy(k,w(1,kw),1,a(1,k),1)
                    if (k > 1) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_wscal(k - 1,r1,a(1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns kw and kw-1 of w now
                    ! hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    if (k > 2) then
                       ! store u(k) and u(k-1) in columns k and k-1 of a
                       d12 = w(k - 1,kw)
                       d11 = w(k,kw)/d12
                       d22 = w(k - 1,kw - 1)/d12
                       t = cone/(d11*d22 - cone)
                       do j = 1,k - 2
                          a(j,k - 1) = t*((d11*w(j,kw - 1) - w(j,kw))/d12)
                          a(j,k) = t*((d22*w(j,kw) - w(j,kw - 1))/d12)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k - 1,k - 1) = w(k - 1,kw - 1)
                    a(k - 1,k) = w(k - 1,kw)
                    a(k,k) = w(k,kw)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              30 continue
              ! update the upper triangle of a11 (= a(1:k,1:k)) as
              ! a11 := a11 - u12*d*u12**t = a11 - u12*w**t
              ! computing blocks of nb columns at a time
              do j = ((k - 1)/nb)*nb + 1,1,-nb
                 jb = min(nb,k - j + 1)
                 ! update the upper triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_wgemv('NO TRANSPOSE',jj - j + 1,n - k,-cone,a(j,k + 1),lda,w(jj, &
                               kw + 1),ldw,cone,a(j,jj),1)
                 end do
                 ! update the rectangular superdiagonal block
                 if (j >= 2) call la_wgemm('NO TRANSPOSE','TRANSPOSE',j - 1,jb,n - k,-cone,a( &
                           1,k + 1),lda,w(j,kw + 1),ldw,cone,a(1,j),lda)
              end do
              ! put u12 in standard form by partially undoing the interchanges
              ! in columns k+1:n
              j = k + 1
              60 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j + 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j + 1
                 if (jp2 /= jj .and. j <= n) call la_wswap(n - j + 1,a(jp2,j),lda,a(jj,j), &
                           lda)
                 jj = j - 1
                 if (jp1 /= jj .and. kstep == 2) call la_wswap(n - j + 1,a(jp1,j),lda,a(jj,j &
                           ),lda)
              if (j <= n) go to 60
              ! set kb to the number of columns factorized
              kb = n - k
           else
              ! factorize the leading columns of a using the lower triangle
              ! of a and working forwards, and compute the matrix w = l21*d
              ! for use in updating a22
              ! k is the main loop index, increasing from 1 in steps of 1 or 2
              k = 1
              70 continue
              ! exit from loop
              if ((k >= nb .and. nb < n) .or. k > n) go to 90
              kstep = 1
              p = k
              ! copy column k of a to column k of w and update it
              call la_wcopy(n - k + 1,a(k,k),1,w(k,k),1)
              if (k > 1) call la_wgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1),lda,w(k, &
                        1),ldw,cone,w(k,k),1)
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(w(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iwamax(n - k,w(k + 1,k),1)
                 colmax = cabs1(w(imax,k))
              else
                 colmax = zero
              end if
              if (max(absakk,colmax) == zero) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 call la_wcopy(n - k + 1,w(k,k),1,a(k,k),1)
              else
                 ! ============================================================
                 ! test for interchange
                 ! equivalent to testing for absakk>=alpha*colmax
                 ! (used to handle nan and inf)
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    72 continue
                       ! begin pivot search loop body
                       ! copy column imax to column k+1 of w and update it
                       call la_wcopy(imax - k,a(imax,k),lda,w(k,k + 1),1)
                       call la_wcopy(n - imax + 1,a(imax,imax),1,w(imax,k + 1),1)
                       if (k > 1) call la_wgemv('NO TRANSPOSE',n - k + 1,k - 1,-cone,a(k,1), &
                                 lda,w(imax,1),ldw,cone,w(k,k + 1),1)
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iwamax(imax - k,w(k,k + 1),1)
                          rowmax = cabs1(w(jmax,k + 1))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iwamax(n - imax,w(imax + 1,k + 1),1)
                          qtemp = cabs1(w(itemp,k + 1))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for
                       ! cabs1( w( imax, k+1 ) )>=alpha*rowmax
                       ! (used to handle nan and inf)
                       if (.not. (cabs1(w(imax,k + 1)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          ! copy column k+1 of w to column k of w
                          call la_wcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                          done = .true.
                       ! equivalent to testing for rowmax==colmax,
                       ! (used to handle nan and inf)
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found: set params and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                          ! copy updated jmaxth (next imaxth) column to kth of w
                          call la_wcopy(n - k + 1,w(k,k + 1),1,w(k,k),1)
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 72
                 end if
                 ! ============================================================
                 kk = k + kstep - 1
                 if ((kstep == 2) .and. (p /= k)) then
                    ! copy non-updated column k to column p
                    call la_wcopy(p - k,a(k,k),1,a(p,k),lda)
                    call la_wcopy(n - p + 1,a(p,k),1,a(p,p),1)
                    ! interchange rows k and p in first k columns of a
                    ! and first k+1 columns of w
                    call la_wswap(k,a(k,1),lda,a(p,1),lda)
                    call la_wswap(kk,w(k,1),ldw,w(p,1),ldw)
                 end if
                 ! updated column kp is already stored in column kk of w
                 if (kp /= kk) then
                    ! copy non-updated column kk to column kp
                    a(kp,k) = a(kk,k)
                    call la_wcopy(kp - k - 1,a(k + 1,kk),1,a(kp,k + 1),lda)
                    call la_wcopy(n - kp + 1,a(kp,kk),1,a(kp,kp),1)
                    ! interchange rows kk and kp in first kk columns of a and w
                    call la_wswap(kk,a(kk,1),lda,a(kp,1),lda)
                    call la_wswap(kk,w(kk,1),ldw,w(kp,1),ldw)
                 end if
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k of w now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    ! store l(k) in column k of a
                    call la_wcopy(n - k + 1,w(k,k),1,a(k,k),1)
                    if (k < n) then
                       if (cabs1(a(k,k)) >= sfmin) then
                          r1 = cone/a(k,k)
                          call la_wscal(n - k,r1,a(k + 1,k),1)
                       else if (a(k,k) /= czero) then
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/a(k,k)
                          end do
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 of w now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    if (k < n - 1) then
                       ! store l(k) and l(k+1) in columns k and k+1 of a
                       d21 = w(k + 1,k)
                       d11 = w(k + 1,k + 1)/d21
                       d22 = w(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          a(j,k) = t*((d11*w(j,k) - w(j,k + 1))/d21)
                          a(j,k + 1) = t*((d22*w(j,k + 1) - w(j,k))/d21)
                       end do
                    end if
                    ! copy d(k) to a
                    a(k,k) = w(k,k)
                    a(k + 1,k) = w(k + 1,k)
                    a(k + 1,k + 1) = w(k + 1,k + 1)
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 70
              90 continue
              ! update the lower triangle of a22 (= a(k:n,k:n)) as
              ! a22 := a22 - l21*d*l21**t = a22 - l21*w**t
              ! computing blocks of nb columns at a time
              do j = k,n,nb
                 jb = min(nb,n - j + 1)
                 ! update the lower triangle of the diagonal block
                 do jj = j,j + jb - 1
                    call la_wgemv('NO TRANSPOSE',j + jb - jj,k - 1,-cone,a(jj,1),lda,w(jj, &
                               1),ldw,cone,a(jj,jj),1)
                 end do
                 ! update the rectangular subdiagonal block
                 if (j + jb <= n) call la_wgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,k - 1,- &
                           cone,a(j + jb,1),lda,w(j,1),ldw,cone,a(j + jb,j),lda)
              end do
              ! put l21 in standard form by partially undoing the interchanges
              ! in columns 1:k-1
              j = k - 1
              120 continue
                 kstep = 1
                 jp1 = 1
                 jj = j
                 jp2 = ipiv(j)
                 if (jp2 < 0) then
                    jp2 = -jp2
                    j = j - 1
                    jp1 = -ipiv(j)
                    kstep = 2
                 end if
                 j = j - 1
                 if (jp2 /= jj .and. j >= 1) call la_wswap(j,a(jp2,1),lda,a(jj,1),lda)

                 jj = j + 1
                 if (jp1 /= jj .and. kstep == 2) call la_wswap(j,a(jp1,1),lda,a(jj,1), &
                           lda)
              if (j >= 1) go to 120
              ! set kb to the number of columns factorized
              kb = k - 1
           end if
           return
     end subroutine la_wlasyf_rook
#endif

     !> CSPTRI: computes the inverse of a complex symmetric indefinite matrix
     !> A in packed storage using the factorization A = U*D*U**T or
     !> A = L*D*L**T computed by CSPTRF.

     pure subroutine la_csptri(uplo,n,ap,ipiv,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(sp),intent(inout) :: ap(*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,k,kc,kcnext,kp,kpc,kstep,kx,npp
           complex(sp) :: ak,akkp1,akp1,d,t,temp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('CSPTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              kp = n*(n + 1)/2
              do info = n,1,-1
                 if (ipiv(info) > 0 .and. ap(kp) == czero) return
                 kp = kp - info
