                    call la_ccopy(k - 1,ap(kc),1,work,1)
                    call la_cspmv(uplo,k - 1,-cone,ap,work,1,czero,ap(kc),1)
                    ap(kc + k - 1) = ap(kc + k - 1) - la_cdotu(k - 1,work,1,ap(kc),1)
                 end if
                 kstep = 1
              else
