                    ap(kcnext + 1) = ap(kcnext + 1) - la_cdotu(n - k,ap(kc + 1),1,ap(kcnext + &
                              2),1)
                    call la_ccopy(n - k,ap(kcnext + 2),1,work,1)
                    call la_cspmv(uplo,n - k,-cone,ap(kc + (n - k + 1)),work,1,czero,ap( &
                              kcnext + 2),1)
                    ap(kcnext) = ap(kcnext) - la_cdotu(n - k,work,1,ap(kcnext + 2),1)

