                 do j = k + 1,kp - 1
                    kx = kx + n - j + 1
                    temp = ap(kc + j - k)
                    ap(kc + j - k) = ap(kx)
                    ap(kx) = temp
                 end do
                 temp = ap(kc)
                 ap(kc) = ap(kpc)
                 ap(kpc) = temp
                 if (kstep == 2) then
                    temp = ap(kc - n + k - 1)
                    ap(kc - n + k - 1) = ap(kc - n + kp - 1)
                    ap(kc - n + kp - 1) = temp
                 end if
              end if
              k = k - kstep
              kc = kcnext
              go to 60
              80 continue
           end if
           return
     end subroutine la_csptri
