                    call la_wgemv('TRANSPOSE',n - k,nrhs,-cone,b(k + 1,1),ldb,ap(kc + 1), &
                               1,cone,b(k,1),ldb)
                    call la_wgemv('TRANSPOSE',n - k,nrhs,-cone,b(k + 1,1),ldb,ap(kc - (n - &
                              k)),1,cone,b(k - 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k).
                 kp = -ipiv(k)
                 if (kp /= k) call la_wswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kc = kc - (n - k + 2)
                 k = k - 2
              end if
              go to 90
              100 continue
           end if
           return
     end subroutine la_wsptrs
