     !> If parameter WAY = 'C':
     !> CSYCONVF: converts the factorization output format used in
     !> CSYTRF provided on entry in parameter A into the factorization
     !> output format used in CSYTRF_RK (or CSYTRF_BK) that is stored
     !> on exit in parameters A and E. It also converts in place details of
     !> the intechanges stored in IPIV from the format used in CSYTRF into
     !> the format used in CSYTRF_RK (or CSYTRF_BK).
     !> If parameter WAY = 'R':
     !> CSYCONVF performs the conversion in reverse direction, i.e.
     !> converts the factorization output format used in CSYTRF_RK
     !> (or CSYTRF_BK) provided on entry in parameters A and E into
     !> the factorization output format used in CSYTRF that is stored
     !> on exit in parameter A. It also converts in place details of
     !> the intechanges stored in IPIV from the format used in CSYTRF_RK
     !> (or CSYTRF_BK) into the format used in CSYTRF.
     !> CSYCONVF can also convert in Hermitian matrix case, i.e. between
     !> formats used in CHETRF and CHETRF_RK (or CHETRF_BK).

     pure subroutine la_csyconvf(uplo,way,n,a,lda,e,ipiv,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo,way
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(inout) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*),e(*)
        ! =====================================================================

           ! External Subroutines
           logical(lk) :: upper,convert
           integer(ilp) :: i,ip
           ! Executable Statements
           info = 0
           upper = la_lsame(uplo,'U')
           convert = la_lsame(way,'C')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (.not. convert .and. .not. la_lsame(way,'R')) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('CSYCONVF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (upper) then
              ! begin a is upper
              if (convert) then
                 ! convert a (a is upper)
                 ! convert value
                 ! assign superdiagonal entries of d to array e and czero out
                 ! corresponding entries in input storage a
                 i = n
                 e(1) = czero
                 do while (i > 1)
                    if (ipiv(i) < 0) then
                       e(i) = a(i - 1,i)
                       e(i - 1) = czero
                       a(i - 1,i) = czero
                       i = i - 1
                    else
                       e(i) = czero
                    end if
                    i = i - 1
                 end do
                 ! convert permutations and ipiv
                 ! apply permutations to submatrices of upper part of a
                 ! in factorization order where i decreases from n to 1
                 i = n
                 do while (i >= 1)
                    if (ipiv(i) > 0) then
                       ! 1-by-1 pivot interchange
                       ! swap rows i and ipiv(i) in a(1:i,n-i:n)
                       ip = ipiv(i)
                       if (i < n) then
                          if (ip /= i) then
                             call la_cswap(n - i,a(i,i + 1),lda,a(ip,i + 1),lda)
                          end if
                       end if
                    else
                       ! 2-by-2 pivot interchange
                       ! swap rows i-1 and ipiv(i) in a(1:i,n-i:n)
                       ip = -ipiv(i)
                       if (i < n) then
                          if (ip /= (i - 1)) then
                             call la_cswap(n - i,a(i - 1,i + 1),lda,a(ip,i + 1),lda)

                          end if
                       end if
                       ! convert ipiv
                       ! there is no interchnge of rows i and and ipiv(i),
                       ! so this should be reflected in ipiv format for
                       ! *sytrf_rk ( or *sytrf_bk)
                       ipiv(i) = i
                       i = i - 1
                    end if
                    i = i - 1
                 end do
              else
                 ! revert a (a is upper)
                 ! revert permutations and ipiv
                 ! apply permutations to submatrices of upper part of a
                 ! in reverse factorization order where i increases from 1 to n
                 i = 1
                 do while (i <= n)
                    if (ipiv(i) > 0) then
                       ! 1-by-1 pivot interchange
                       ! swap rows i and ipiv(i) in a(1:i,n-i:n)
                       ip = ipiv(i)
                       if (i < n) then
                          if (ip /= i) then
                             call la_cswap(n - i,a(ip,i + 1),lda,a(i,i + 1),lda)
                          end if
                       end if
                    else
                       ! 2-by-2 pivot interchange
                       ! swap rows i-1 and ipiv(i) in a(1:i,n-i:n)
                       i = i + 1
                       ip = -ipiv(i)
                       if (i < n) then
                          if (ip /= (i - 1)) then
                             call la_cswap(n - i,a(ip,i + 1),lda,a(i - 1,i + 1),lda)

                          end if
                       end if
                       ! convert ipiv
                       ! there is cone interchange of rows i-1 and ipiv(i-1),
                       ! so this should be recorded in two consecutive entries
                       ! in ipiv format for *sytrf
                       ipiv(i) = ipiv(i - 1)
                    end if
                    i = i + 1
                 end do
                 ! revert value
                 ! assign superdiagonal entries of d from array e to
                 ! superdiagonal entries of a.
                 i = n
                 do while (i > 1)
                    if (ipiv(i) < 0) then
                       a(i - 1,i) = e(i)
                       i = i - 1
                    end if
                    i = i - 1
                 end do
