                       if (i > 1) then
                          if (ip /= i) then
                             call la_wswap(i - 1,a(i,1),lda,a(ip,1),lda)
                          end if
                          if (ip2 /= (i + 1)) then
                             call la_wswap(i - 1,a(i + 1,1),lda,a(ip2,1),lda)
                          end if
                       end if
                       i = i + 1
                    end if
                    i = i + 1
                 end do
              else
                 ! revert a (a is lower)
                 ! revert permutations
                 ! apply permutations to submatrices of lower part of a
                 ! in reverse factorization order where i decreases from n to 1
                 i = n
                 do while (i >= 1)
                    if (ipiv(i) > 0) then
                       ! 1-by-1 pivot interchange
                       ! swap rows i and ipiv(i) in a(i:n,1:i-1)
                       ip = ipiv(i)
                       if (i > 1) then
                          if (ip /= i) then
                             call la_wswap(i - 1,a(ip,1),lda,a(i,1),lda)
                          end if
                       end if
                    else
                       ! 2-by-2 pivot interchange
                       ! swap rows i+1 and ipiv(i+1) and i and ipiv(i)
                       ! in a(i:n,1:i-1)
                       i = i - 1
                       ip = -ipiv(i)
                       ip2 = -ipiv(i + 1)
                       if (i > 1) then
                          if (ip2 /= (i + 1)) then
                             call la_wswap(i - 1,a(ip2,1),lda,a(i + 1,1),lda)
                          end if
                          if (ip /= i) then
                             call la_wswap(i - 1,a(ip,1),lda,a(i,1),lda)
                          end if
                       end if
                    end if
                    i = i - 1
                 end do
                 ! revert value
                 ! assign subdiagonal entries of d from array e to
                 ! subgiagonal entries of a.
                 i = 1
                 do while (i <= n - 1)
                    if (ipiv(i) < 0) then
                       a(i + 1,i) = e(i)
                       i = i + 1
                    end if
                    i = i + 1
                 end do
              end if
              ! end a is lower
           end if
           return
     end subroutine la_wsyconvf_rook
#endif

     !> CSYTF2_RK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman (rook) diagonal pivoting method:
     !> A = P*U*D*(U**T)*(P**T) or A = P*L*D*(L**T)*(P**T),
     !> where U (or L) is unit upper (or lower) triangular matrix,
     !> U**T (or L**T) is the transpose of U (or L), P is a permutation
     !> matrix, P**T is the transpose of P, and D is symmetric and block
     !> diagonal with 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.
     !> For more information see Further Details section.

     pure subroutine la_csytf2_rk(uplo,n,a,lda,e,ipiv,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: e(*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: sevten = 17.0e+0_sp

           ! Local Scalars
           logical(lk) :: upper,done
           integer(ilp) :: i,imax,j,jmax,itemp,k,kk,kp,kstep,p,ii
           real(sp) :: absakk,alpha,colmax,rowmax,stemp,sfmin
           complex(sp) :: d11,d12,d21,d22,t,wk,wkm1,wkp1,z
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt,aimag,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=sp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CSYTF2_RK',-info)
              return
           end if
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_slamch('S')
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 34
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_icamax(k - 1,a(1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange,
                    ! use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_icamax(k - imax,a(imax,imax + 1),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_icamax(imax - 1,a(1,imax),1)
                          stemp = cabs1(a(itemp,imax))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the leading
                    ! submatrix a(1:k,1:k) if we have a 2-by-2 pivot
                    if (p > 1) call la_cswap(p - 1,a(1,k),1,a(1,p),1)
                    if (p < (k - 1)) call la_cswap(k - p - 1,a(p + 1,k),1,a(p,p + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_cswap(n - k,a(k,k + 1),lda,a(p,k + 1),lda)
                 end if
                 ! second swap
                 kk = k - kstep + 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the leading
                    ! submatrix a(1:k,1:k)
                    if (kp > 1) call la_cswap(kp - 1,a(1,kk),1,a(1,kp),1)
                    if ((kk > 1) .and. (kp < (kk - 1))) call la_cswap(kk - kp - 1,a(kp + 1,kk), &
                              1,a(kp,kp + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k - 1,k)
                       a(k - 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_cswap(n - k,a(kk,k + 1),lda,a(kp,k + 1),lda)
                 end if
                 ! update the leading submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    if (k > 1) then
                       ! perform a rank-1 update of a(1:k-1,1:k-1) and
                       ! store u(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(1:k-1,1:k-1) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*1/d(k)*w(k)**t
                          d11 = cone/a(k,k)
                          call la_csyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                          ! store u(k) in column k
                          call la_cscal(k - 1,d11,a(1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_csyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k-1 now hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    ! perform a rank-2 update of a(1:k-2,1:k-2) as
                    ! a := a - ( u(k-1) u(k) )*d(k)*( u(k-1) u(k) )**t
                       ! = a - ( ( a(k-1)a(k) )*inv(d(k)) ) * ( a(k-1)a(k) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k > 2) then
                       d12 = a(k - 1,k)
                       d22 = a(k - 1,k - 1)/d12
                       d11 = a(k,k)/d12
                       t = cone/(d11*d22 - cone)
                       do j = k - 2,1,-1
                          wkm1 = t*(d11*a(j,k - 1) - a(j,k))
                          wk = t*(d22*a(j,k) - a(j,k - 1))
                          do i = j,1,-1
                             a(i,j) = a(i,j) - (a(i,k)/d12)*wk - (a(i,k - 1)/d12) &
                                       *wkm1
                          end do
                          ! store u(k) and u(k-1) in cols k and k-1 for row j
                          a(j,k) = wk/d12
                          a(j,k - 1) = wkm1/d12
                       end do
                    end if
                    ! copy superdiagonal elements of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    e(k) = a(k - 1,k)
                    e(k - 1) = czero
                    a(k - 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              34 continue
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2
              k = 1
              40 continue
              ! if k > n, exit from loop
              if (k > n) go to 64
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_icamax(n - k,a(k + 1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    42 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_icamax(imax - k,a(imax,k),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_icamax(n - imax,a(imax + 1,imax),1)
                          stemp = cabs1(a(itemp,imax))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 42
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the trailing
                    ! submatrix a(k:n,k:n) if we have a 2-by-2 pivot
                    if (p < n) call la_cswap(n - p,a(p + 1,k),1,a(p + 1,p),1)
                    if (p > (k + 1)) call la_cswap(p - k - 1,a(k + 1,k),1,a(p,k + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_cswap(k - 1,a(k,1),lda,a(p,1),lda)
                 end if
                 ! second swap
                 kk = k + kstep - 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the trailing
                    ! submatrix a(k:n,k:n)
                    if (kp < n) call la_cswap(n - kp,a(kp + 1,kk),1,a(kp + 1,kp),1)

                    if ((kk < n) .and. (kp > (kk + 1))) call la_cswap(kp - kk - 1,a(kk + 1,kk), &
                              1,a(kp,kk + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k + 1,k)
                       a(k + 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_cswap(k - 1,a(kk,1),lda,a(kp,1),lda)
                 end if
                 ! update the trailing submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    if (k < n) then
                    ! perform a rank-1 update of a(k+1:n,k+1:n) and
                    ! store l(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                          d11 = cone/a(k,k)
                          call la_csyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                          ! store l(k) in column k
                          call la_cscal(n - k,d11,a(k + 1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_csyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    ! perform a rank-2 update of a(k+2:n,k+2:n) as
                    ! a := a - ( l(k) l(k+1) ) * d(k) * ( l(k) l(k+1) )**t
                       ! = a - ( ( a(k)a(k+1) )*inv(d(k) ) * ( a(k)a(k+1) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k < n - 1) then
                       d21 = a(k + 1,k)
                       d11 = a(k + 1,k + 1)/d21
                       d22 = a(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          ! compute  d21 * ( w(k)w(k+1) ) * inv(d(k)) for row j
                          wk = t*(d11*a(j,k) - a(j,k + 1))
                          wkp1 = t*(d22*a(j,k + 1) - a(j,k))
                          ! perform a rank-2 update of a(k+2:n,k+2:n)
                          do i = j,n
                             a(i,j) = a(i,j) - (a(i,k)/d21)*wk - (a(i,k + 1)/d21) &
                                       *wkp1
                          end do
                          ! store l(k) and l(k+1) in cols k and k+1 for row j
                          a(j,k) = wk/d21
                          a(j,k + 1) = wkp1/d21
                       end do
                    end if
                    ! copy subdiagonal elements of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    e(k) = a(k + 1,k)
                    e(k + 1) = czero
                    a(k + 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 40
              64 continue
           end if
           return
     end subroutine la_csytf2_rk
     !> ZSYTF2_RK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman (rook) diagonal pivoting method:
     !> A = P*U*D*(U**T)*(P**T) or A = P*L*D*(L**T)*(P**T),
     !> where U (or L) is unit upper (or lower) triangular matrix,
     !> U**T (or L**T) is the transpose of U (or L), P is a permutation
     !> matrix, P**T is the transpose of P, and D is symmetric and block
     !> diagonal with 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.
     !> For more information see Further Details section.

     pure subroutine la_zsytf2_rk(uplo,n,a,lda,e,ipiv,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(out) :: e(*)
        ! =====================================================================
           ! Parameters
           real(dp),parameter :: sevten = 17.0e+0_dp

           ! Local Scalars
           logical(lk) :: upper,done
           integer(ilp) :: i,imax,j,jmax,itemp,k,kk,kp,kstep,p,ii
           real(dp) :: absakk,alpha,colmax,rowmax,dtemp,sfmin
           complex(dp) :: d11,d12,d21,d22,t,wk,wkm1,wkp1,z
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt,aimag,real
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=dp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('ZSYTF2_RK',-info)
              return
           end if
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_dlamch('S')
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 34
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_izamax(k - 1,a(1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange,
                    ! use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_izamax(k - imax,a(imax,imax + 1),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_izamax(imax - 1,a(1,imax),1)
                          dtemp = cabs1(a(itemp,imax))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the leading
                    ! submatrix a(1:k,1:k) if we have a 2-by-2 pivot
                    if (p > 1) call la_zswap(p - 1,a(1,k),1,a(1,p),1)
                    if (p < (k - 1)) call la_zswap(k - p - 1,a(p + 1,k),1,a(p,p + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_zswap(n - k,a(k,k + 1),lda,a(p,k + 1),lda)
                 end if
                 ! second swap
                 kk = k - kstep + 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the leading
                    ! submatrix a(1:k,1:k)
                    if (kp > 1) call la_zswap(kp - 1,a(1,kk),1,a(1,kp),1)
                    if ((kk > 1) .and. (kp < (kk - 1))) call la_zswap(kk - kp - 1,a(kp + 1,kk), &
                              1,a(kp,kp + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k - 1,k)
                       a(k - 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_zswap(n - k,a(kk,k + 1),lda,a(kp,k + 1),lda)
                 end if
                 ! update the leading submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    if (k > 1) then
                       ! perform a rank-1 update of a(1:k-1,1:k-1) and
                       ! store u(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(1:k-1,1:k-1) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*1/d(k)*w(k)**t
                          d11 = cone/a(k,k)
                          call la_zsyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                          ! store u(k) in column k
                          call la_zscal(k - 1,d11,a(1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_zsyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k-1 now hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    ! perform a rank-2 update of a(1:k-2,1:k-2) as
                    ! a := a - ( u(k-1) u(k) )*d(k)*( u(k-1) u(k) )**t
                       ! = a - ( ( a(k-1)a(k) )*inv(d(k)) ) * ( a(k-1)a(k) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k > 2) then
                       d12 = a(k - 1,k)
                       d22 = a(k - 1,k - 1)/d12
                       d11 = a(k,k)/d12
                       t = cone/(d11*d22 - cone)
                       do j = k - 2,1,-1
                          wkm1 = t*(d11*a(j,k - 1) - a(j,k))
                          wk = t*(d22*a(j,k) - a(j,k - 1))
                          do i = j,1,-1
                             a(i,j) = a(i,j) - (a(i,k)/d12)*wk - (a(i,k - 1)/d12) &
                                       *wkm1
                          end do
                          ! store u(k) and u(k-1) in cols k and k-1 for row j
                          a(j,k) = wk/d12
                          a(j,k - 1) = wkm1/d12
                       end do
                    end if
                    ! copy superdiagonal elements of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    e(k) = a(k - 1,k)
                    e(k - 1) = czero
                    a(k - 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              34 continue
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2
              k = 1
              40 continue
              ! if k > n, exit from loop
              if (k > n) go to 64
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_izamax(n - k,a(k + 1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    42 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_izamax(imax - k,a(imax,k),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_izamax(n - imax,a(imax + 1,imax),1)
                          dtemp = cabs1(a(itemp,imax))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 42
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the trailing
                    ! submatrix a(k:n,k:n) if we have a 2-by-2 pivot
                    if (p < n) call la_zswap(n - p,a(p + 1,k),1,a(p + 1,p),1)
                    if (p > (k + 1)) call la_zswap(p - k - 1,a(k + 1,k),1,a(p,k + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_zswap(k - 1,a(k,1),lda,a(p,1),lda)
                 end if
                 ! second swap
                 kk = k + kstep - 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the trailing
                    ! submatrix a(k:n,k:n)
                    if (kp < n) call la_zswap(n - kp,a(kp + 1,kk),1,a(kp + 1,kp),1)

                    if ((kk < n) .and. (kp > (kk + 1))) call la_zswap(kp - kk - 1,a(kk + 1,kk), &
                              1,a(kp,kk + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k + 1,k)
                       a(k + 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_zswap(k - 1,a(kk,1),lda,a(kp,1),lda)
                 end if
                 ! update the trailing submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    if (k < n) then
                    ! perform a rank-1 update of a(k+1:n,k+1:n) and
                    ! store l(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                          d11 = cone/a(k,k)
                          call la_zsyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                          ! store l(k) in column k
                          call la_zscal(n - k,d11,a(k + 1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_zsyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    ! perform a rank-2 update of a(k+2:n,k+2:n) as
                    ! a := a - ( l(k) l(k+1) ) * d(k) * ( l(k) l(k+1) )**t
                       ! = a - ( ( a(k)a(k+1) )*inv(d(k) ) * ( a(k)a(k+1) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k < n - 1) then
                       d21 = a(k + 1,k)
                       d11 = a(k + 1,k + 1)/d21
                       d22 = a(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          ! compute  d21 * ( w(k)w(k+1) ) * inv(d(k)) for row j
                          wk = t*(d11*a(j,k) - a(j,k + 1))
                          wkp1 = t*(d22*a(j,k + 1) - a(j,k))
                          ! perform a rank-2 update of a(k+2:n,k+2:n)
                          do i = j,n
                             a(i,j) = a(i,j) - (a(i,k)/d21)*wk - (a(i,k + 1)/d21) &
                                       *wkp1
                          end do
                          ! store l(k) and l(k+1) in cols k and k+1 for row j
                          a(j,k) = wk/d21
                          a(j,k + 1) = wkp1/d21
                       end do
                    end if
                    ! copy subdiagonal elements of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    e(k) = a(k + 1,k)
                    e(k + 1) = czero
                    a(k + 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 40
              64 continue
           end if
           return
     end subroutine la_zsytf2_rk
#ifdef LA_WITH_XDP
     !> YSYTF2_RK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman (rook) diagonal pivoting method:
     !> A = P*U*D*(U**T)*(P**T) or A = P*L*D*(L**T)*(P**T),
     !> where U (or L) is unit upper (or lower) triangular matrix,
     !> U**T (or L**T) is the transpose of U (or L), P is a permutation
     !> matrix, P**T is the transpose of P, and D is symmetric and block
     !> diagonal with 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.
     !> For more information see Further Details section.

     pure subroutine la_ysytf2_rk(uplo,n,a,lda,e,ipiv,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: e(*)
        ! =====================================================================
           ! Parameters
           real(xdp),parameter :: sevten = 17.0e+0_xdp

           ! Local Scalars
           logical(lk) :: upper,done
           integer(ilp) :: i,imax,j,jmax,itemp,k,kk,kp,kstep,p,ii
           real(xdp) :: absakk,alpha,colmax,rowmax,xtemp,sfmin
           complex(xdp) :: d11,d12,d21,d22,t,wk,wkm1,wkp1,z
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt,aimag,real
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=xdp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('YSYTF2_RK',-info)
              return
           end if
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_xlamch('S')
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 34
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iyamax(k - 1,a(1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange,
                    ! use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iyamax(k - imax,a(imax,imax + 1),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iyamax(imax - 1,a(1,imax),1)
                          xtemp = cabs1(a(itemp,imax))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the leading
                    ! submatrix a(1:k,1:k) if we have a 2-by-2 pivot
                    if (p > 1) call la_yswap(p - 1,a(1,k),1,a(1,p),1)
                    if (p < (k - 1)) call la_yswap(k - p - 1,a(p + 1,k),1,a(p,p + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_yswap(n - k,a(k,k + 1),lda,a(p,k + 1),lda)
                 end if
                 ! second swap
                 kk = k - kstep + 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the leading
                    ! submatrix a(1:k,1:k)
                    if (kp > 1) call la_yswap(kp - 1,a(1,kk),1,a(1,kp),1)
                    if ((kk > 1) .and. (kp < (kk - 1))) call la_yswap(kk - kp - 1,a(kp + 1,kk), &
                              1,a(kp,kp + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k - 1,k)
                       a(k - 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_yswap(n - k,a(kk,k + 1),lda,a(kp,k + 1),lda)
                 end if
                 ! update the leading submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    if (k > 1) then
                       ! perform a rank-1 update of a(1:k-1,1:k-1) and
                       ! store u(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(1:k-1,1:k-1) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*1/d(k)*w(k)**t
                          d11 = cone/a(k,k)
                          call la_ysyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                          ! store u(k) in column k
                          call la_yscal(k - 1,d11,a(1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_ysyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k-1 now hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    ! perform a rank-2 update of a(1:k-2,1:k-2) as
                    ! a := a - ( u(k-1) u(k) )*d(k)*( u(k-1) u(k) )**t
                       ! = a - ( ( a(k-1)a(k) )*inv(d(k)) ) * ( a(k-1)a(k) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k > 2) then
                       d12 = a(k - 1,k)
                       d22 = a(k - 1,k - 1)/d12
                       d11 = a(k,k)/d12
                       t = cone/(d11*d22 - cone)
                       do j = k - 2,1,-1
                          wkm1 = t*(d11*a(j,k - 1) - a(j,k))
                          wk = t*(d22*a(j,k) - a(j,k - 1))
                          do i = j,1,-1
                             a(i,j) = a(i,j) - (a(i,k)/d12)*wk - (a(i,k - 1)/d12) &
                                       *wkm1
                          end do
                          ! store u(k) and u(k-1) in cols k and k-1 for row j
                          a(j,k) = wk/d12
                          a(j,k - 1) = wkm1/d12
                       end do
                    end if
                    ! copy superdiagonal elements of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    e(k) = a(k - 1,k)
                    e(k - 1) = czero
                    a(k - 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              34 continue
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2
              k = 1
              40 continue
              ! if k > n, exit from loop
              if (k > n) go to 64
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iyamax(n - k,a(k + 1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    42 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iyamax(imax - k,a(imax,k),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iyamax(n - imax,a(imax + 1,imax),1)
                          xtemp = cabs1(a(itemp,imax))
                          if (xtemp > rowmax) then
                             rowmax = xtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 42
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the trailing
                    ! submatrix a(k:n,k:n) if we have a 2-by-2 pivot
                    if (p < n) call la_yswap(n - p,a(p + 1,k),1,a(p + 1,p),1)
                    if (p > (k + 1)) call la_yswap(p - k - 1,a(k + 1,k),1,a(p,k + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_yswap(k - 1,a(k,1),lda,a(p,1),lda)
                 end if
                 ! second swap
                 kk = k + kstep - 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the trailing
                    ! submatrix a(k:n,k:n)
                    if (kp < n) call la_yswap(n - kp,a(kp + 1,kk),1,a(kp + 1,kp),1)

                    if ((kk < n) .and. (kp > (kk + 1))) call la_yswap(kp - kk - 1,a(kk + 1,kk), &
                              1,a(kp,kk + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k + 1,k)
                       a(k + 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_yswap(k - 1,a(kk,1),lda,a(kp,1),lda)
                 end if
                 ! update the trailing submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    if (k < n) then
                    ! perform a rank-1 update of a(k+1:n,k+1:n) and
                    ! store l(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                          d11 = cone/a(k,k)
                          call la_ysyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                          ! store l(k) in column k
                          call la_yscal(n - k,d11,a(k + 1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_ysyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    ! perform a rank-2 update of a(k+2:n,k+2:n) as
                    ! a := a - ( l(k) l(k+1) ) * d(k) * ( l(k) l(k+1) )**t
                       ! = a - ( ( a(k)a(k+1) )*inv(d(k) ) * ( a(k)a(k+1) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k < n - 1) then
                       d21 = a(k + 1,k)
                       d11 = a(k + 1,k + 1)/d21
                       d22 = a(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          ! compute  d21 * ( w(k)w(k+1) ) * inv(d(k)) for row j
                          wk = t*(d11*a(j,k) - a(j,k + 1))
                          wkp1 = t*(d22*a(j,k + 1) - a(j,k))
                          ! perform a rank-2 update of a(k+2:n,k+2:n)
                          do i = j,n
                             a(i,j) = a(i,j) - (a(i,k)/d21)*wk - (a(i,k + 1)/d21) &
                                       *wkp1
                          end do
                          ! store l(k) and l(k+1) in cols k and k+1 for row j
                          a(j,k) = wk/d21
                          a(j,k + 1) = wkp1/d21
                       end do
                    end if
                    ! copy subdiagonal elements of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    e(k) = a(k + 1,k)
                    e(k + 1) = czero
                    a(k + 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 40
              64 continue
           end if
           return
     end subroutine la_ysytf2_rk
#endif
#ifdef LA_WITH_QP
     !> WSYTF2_RK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman (rook) diagonal pivoting method:
     !> A = P*U*D*(U**T)*(P**T) or A = P*L*D*(L**T)*(P**T),
     !> where U (or L) is unit upper (or lower) triangular matrix,
     !> U**T (or L**T) is the transpose of U (or L), P is a permutation
     !> matrix, P**T is the transpose of P, and D is symmetric and block
     !> diagonal with 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.
     !> For more information see Further Details section.

     pure subroutine la_wsytf2_rk(uplo,n,a,lda,e,ipiv,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: e(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: sevten = 17.0e+0_qp

           ! Local Scalars
           logical(lk) :: upper,done
           integer(ilp) :: i,imax,j,jmax,itemp,k,kk,kp,kstep,p,ii
           real(qp) :: absakk,alpha,colmax,rowmax,qtemp,sfmin
           complex(qp) :: d11,d12,d21,d22,t,wk,wkm1,wkp1,z
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt,aimag,real
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=qp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('WSYTF2_RK',-info)
              return
           end if
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_qlamch('S')
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! initialize the first entry of array e, where superdiagonal
              ! elements of d are stored
              e(1) = czero
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 34
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_iwamax(k - 1,a(1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k > 1) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange,
                    ! use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_iwamax(k - imax,a(imax,imax + 1),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_iwamax(imax - 1,a(1,imax),1)
                          qtemp = cabs1(a(itemp,imax))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the leading
                    ! submatrix a(1:k,1:k) if we have a 2-by-2 pivot
                    if (p > 1) call la_wswap(p - 1,a(1,k),1,a(1,p),1)
                    if (p < (k - 1)) call la_wswap(k - p - 1,a(p + 1,k),1,a(p,p + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_wswap(n - k,a(k,k + 1),lda,a(p,k + 1),lda)
                 end if
                 ! second swap
                 kk = k - kstep + 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the leading
                    ! submatrix a(1:k,1:k)
                    if (kp > 1) call la_wswap(kp - 1,a(1,kk),1,a(1,kp),1)
                    if ((kk > 1) .and. (kp < (kk - 1))) call la_wswap(kk - kp - 1,a(kp + 1,kk), &
                              1,a(kp,kp + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k - 1,k)
                       a(k - 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert upper triangle of a into u form by applying
                    ! the interchanges in columns k+1:n.
                    if (k < n) call la_wswap(n - k,a(kk,k + 1),lda,a(kp,k + 1),lda)
                 end if
                 ! update the leading submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    if (k > 1) then
                       ! perform a rank-1 update of a(1:k-1,1:k-1) and
                       ! store u(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(1:k-1,1:k-1) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*1/d(k)*w(k)**t
                          d11 = cone/a(k,k)
                          call la_wsyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                          ! store u(k) in column k
                          call la_wscal(k - 1,d11,a(1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_wsyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                       end if
                       ! store the superdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k-1 now hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    ! perform a rank-2 update of a(1:k-2,1:k-2) as
                    ! a := a - ( u(k-1) u(k) )*d(k)*( u(k-1) u(k) )**t
                       ! = a - ( ( a(k-1)a(k) )*inv(d(k)) ) * ( a(k-1)a(k) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k > 2) then
                       d12 = a(k - 1,k)
                       d22 = a(k - 1,k - 1)/d12
                       d11 = a(k,k)/d12
                       t = cone/(d11*d22 - cone)
                       do j = k - 2,1,-1
                          wkm1 = t*(d11*a(j,k - 1) - a(j,k))
                          wk = t*(d22*a(j,k) - a(j,k - 1))
                          do i = j,1,-1
                             a(i,j) = a(i,j) - (a(i,k)/d12)*wk - (a(i,k - 1)/d12) &
                                       *wkm1
                          end do
                          ! store u(k) and u(k-1) in cols k and k-1 for row j
                          a(j,k) = wk/d12
                          a(j,k - 1) = wkm1/d12
                       end do
                    end if
                    ! copy superdiagonal elements of d(k) to e(k) and
                    ! zero out superdiagonal entry of a
                    e(k) = a(k - 1,k)
                    e(k - 1) = czero
                    a(k - 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
              34 continue
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! initialize the unused last entry of the subdiagonal array e.
              e(n) = czero
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2
              k = 1
              40 continue
              ! if k > n, exit from loop
              if (k > n) go to 64
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_iwamax(n - k,a(k + 1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
                 ! set e( k ) to zero
                 if (k < n) e(k) = czero
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    42 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_iwamax(imax - k,a(imax,k),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_iwamax(n - imax,a(imax + 1,imax),1)
                          qtemp = cabs1(a(itemp,imax))
                          if (qtemp > rowmax) then
                             rowmax = qtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! abs( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 42
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the trailing
                    ! submatrix a(k:n,k:n) if we have a 2-by-2 pivot
                    if (p < n) call la_wswap(n - p,a(p + 1,k),1,a(p + 1,p),1)
                    if (p > (k + 1)) call la_wswap(p - k - 1,a(k + 1,k),1,a(p,k + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_wswap(k - 1,a(k,1),lda,a(p,1),lda)
                 end if
                 ! second swap
                 kk = k + kstep - 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the trailing
                    ! submatrix a(k:n,k:n)
                    if (kp < n) call la_wswap(n - kp,a(kp + 1,kk),1,a(kp + 1,kp),1)

                    if ((kk < n) .and. (kp > (kk + 1))) call la_wswap(kp - kk - 1,a(kk + 1,kk), &
                              1,a(kp,kk + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k + 1,k)
                       a(k + 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                    ! convert lower triangle of a into l form by applying
                    ! the interchanges in columns 1:k-1.
                    if (k > 1) call la_wswap(k - 1,a(kk,1),lda,a(kp,1),lda)
                 end if
                 ! update the trailing submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    if (k < n) then
                    ! perform a rank-1 update of a(k+1:n,k+1:n) and
                    ! store l(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                          d11 = cone/a(k,k)
                          call la_wsyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                          ! store l(k) in column k
                          call la_wscal(n - k,d11,a(k + 1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_wsyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                       end if
                       ! store the subdiagonal element of d in array e
                       e(k) = czero
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    ! perform a rank-2 update of a(k+2:n,k+2:n) as
                    ! a := a - ( l(k) l(k+1) ) * d(k) * ( l(k) l(k+1) )**t
                       ! = a - ( ( a(k)a(k+1) )*inv(d(k) ) * ( a(k)a(k+1) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k < n - 1) then
                       d21 = a(k + 1,k)
                       d11 = a(k + 1,k + 1)/d21
                       d22 = a(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          ! compute  d21 * ( w(k)w(k+1) ) * inv(d(k)) for row j
                          wk = t*(d11*a(j,k) - a(j,k + 1))
                          wkp1 = t*(d22*a(j,k + 1) - a(j,k))
                          ! perform a rank-2 update of a(k+2:n,k+2:n)
                          do i = j,n
                             a(i,j) = a(i,j) - (a(i,k)/d21)*wk - (a(i,k + 1)/d21) &
                                       *wkp1
                          end do
                          ! store l(k) and l(k+1) in cols k and k+1 for row j
                          a(j,k) = wk/d21
                          a(j,k + 1) = wkp1/d21
                       end do
                    end if
                    ! copy subdiagonal elements of d(k) to e(k) and
                    ! zero out subdiagonal entry of a
                    e(k) = a(k + 1,k)
                    e(k + 1) = czero
                    a(k + 1,k) = czero
                 end if
                 ! end column k is nonsingular
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 40
              64 continue
           end if
           return
     end subroutine la_wsytf2_rk
#endif

     !> CSYTF2_ROOK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman ("rook") diagonal pivoting method:
     !> A = U*D*U**T  or  A = L*D*L**T
     !> where U (or L) is a product of permutation and unit upper (lower)
     !> triangular matrices, U**T is the transpose of U, and D is symmetric and
     !> block diagonal with 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.

     pure subroutine la_csytf2_rook(uplo,n,a,lda,ipiv,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: sevten = 17.0e+0_sp

           ! Local Scalars
           logical(lk) :: upper,done
           integer(ilp) :: i,imax,j,jmax,itemp,k,kk,kp,kstep,p,ii
           real(sp) :: absakk,alpha,colmax,rowmax,stemp,sfmin
           complex(sp) :: d11,d12,d21,d22,t,wk,wkm1,wkp1,z
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt,aimag,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=sp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CSYTF2_ROOK',-info)
              return
           end if
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_slamch('S')
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 70
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_icamax(k - 1,a(1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange,
                    ! use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_icamax(k - imax,a(imax,imax + 1),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_icamax(imax - 1,a(1,imax),1)
                          stemp = cabs1(a(itemp,imax))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! cabs1( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the leading
                    ! submatrix a(1:k,1:k) if we have a 2-by-2 pivot
                    if (p > 1) call la_cswap(p - 1,a(1,k),1,a(1,p),1)
                    if (p < (k - 1)) call la_cswap(k - p - 1,a(p + 1,k),1,a(p,p + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                 end if
                 ! second swap
                 kk = k - kstep + 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the leading
                    ! submatrix a(1:k,1:k)
                    if (kp > 1) call la_cswap(kp - 1,a(1,kk),1,a(1,kp),1)
                    if ((kk > 1) .and. (kp < (kk - 1))) call la_cswap(kk - kp - 1,a(kp + 1,kk), &
                              1,a(kp,kp + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k - 1,k)
                       a(k - 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                 end if
                 ! update the leading submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    if (k > 1) then
                       ! perform a rank-1 update of a(1:k-1,1:k-1) and
                       ! store u(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(1:k-1,1:k-1) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*1/d(k)*w(k)**t
                          d11 = cone/a(k,k)
                          call la_csyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                          ! store u(k) in column k
                          call la_cscal(k - 1,d11,a(1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_csyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k-1 now hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    ! perform a rank-2 update of a(1:k-2,1:k-2) as
                    ! a := a - ( u(k-1) u(k) )*d(k)*( u(k-1) u(k) )**t
                       ! = a - ( ( a(k-1)a(k) )*inv(d(k)) ) * ( a(k-1)a(k) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k > 2) then
                       d12 = a(k - 1,k)
                       d22 = a(k - 1,k - 1)/d12
                       d11 = a(k,k)/d12
                       t = cone/(d11*d22 - cone)
                       do j = k - 2,1,-1
                          wkm1 = t*(d11*a(j,k - 1) - a(j,k))
                          wk = t*(d22*a(j,k) - a(j,k - 1))
                          do i = j,1,-1
                             a(i,j) = a(i,j) - (a(i,k)/d12)*wk - (a(i,k - 1)/d12) &
                                       *wkm1
                          end do
                          ! store u(k) and u(k-1) in cols k and k-1 for row j
                          a(j,k) = wk/d12
                          a(j,k - 1) = wkm1/d12
                       end do
                    end if
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2
              k = 1
              40 continue
              ! if k > n, exit from loop
              if (k > n) go to 70
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_icamax(n - k,a(k + 1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    42 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_icamax(imax - k,a(imax,k),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_icamax(n - imax,a(imax + 1,imax),1)
                          stemp = cabs1(a(itemp,imax))
                          if (stemp > rowmax) then
                             rowmax = stemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! cabs1( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 42
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the trailing
                    ! submatrix a(k:n,k:n) if we have a 2-by-2 pivot
                    if (p < n) call la_cswap(n - p,a(p + 1,k),1,a(p + 1,p),1)
                    if (p > (k + 1)) call la_cswap(p - k - 1,a(k + 1,k),1,a(p,k + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                 end if
                 ! second swap
                 kk = k + kstep - 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the trailing
                    ! submatrix a(k:n,k:n)
                    if (kp < n) call la_cswap(n - kp,a(kp + 1,kk),1,a(kp + 1,kp),1)

                    if ((kk < n) .and. (kp > (kk + 1))) call la_cswap(kp - kk - 1,a(kk + 1,kk), &
                              1,a(kp,kk + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k + 1,k)
                       a(k + 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                 end if
                 ! update the trailing submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    if (k < n) then
                    ! perform a rank-1 update of a(k+1:n,k+1:n) and
                    ! store l(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                          d11 = cone/a(k,k)
                          call la_csyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                          ! store l(k) in column k
                          call la_cscal(n - k,d11,a(k + 1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_csyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    ! perform a rank-2 update of a(k+2:n,k+2:n) as
                    ! a := a - ( l(k) l(k+1) ) * d(k) * ( l(k) l(k+1) )**t
                       ! = a - ( ( a(k)a(k+1) )*inv(d(k) ) * ( a(k)a(k+1) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k < n - 1) then
                       d21 = a(k + 1,k)
                       d11 = a(k + 1,k + 1)/d21
                       d22 = a(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          ! compute  d21 * ( w(k)w(k+1) ) * inv(d(k)) for row j
                          wk = t*(d11*a(j,k) - a(j,k + 1))
                          wkp1 = t*(d22*a(j,k + 1) - a(j,k))
                          ! perform a rank-2 update of a(k+2:n,k+2:n)
                          do i = j,n
                             a(i,j) = a(i,j) - (a(i,k)/d21)*wk - (a(i,k + 1)/d21) &
                                       *wkp1
                          end do
                          ! store l(k) and l(k+1) in cols k and k+1 for row j
                          a(j,k) = wk/d21
                          a(j,k + 1) = wkp1/d21
                       end do
                    end if
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 40
           end if
           70 continue
           return
     end subroutine la_csytf2_rook
     !> ZSYTF2_ROOK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman ("rook") diagonal pivoting method:
     !> A = U*D*U**T  or  A = L*D*L**T
     !> where U (or L) is a product of permutation and unit upper (lower)
     !> triangular matrices, U**T is the transpose of U, and D is symmetric and
     !> block diagonal with 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.

     pure subroutine la_zsytf2_rook(uplo,n,a,lda,ipiv,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(dp),intent(inout) :: a(lda,*)
        ! =====================================================================
           ! Parameters
           real(dp),parameter :: sevten = 17.0e+0_dp

           ! Local Scalars
           logical(lk) :: upper,done
           integer(ilp) :: i,imax,j,jmax,itemp,k,kk,kp,kstep,p,ii
           real(dp) :: absakk,alpha,colmax,rowmax,dtemp,sfmin
           complex(dp) :: d11,d12,d21,d22,t,wk,wkm1,wkp1,z
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt,aimag,real
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(z) = abs(real(z,KIND=dp)) + abs(aimag(z))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('ZSYTF2_ROOK',-info)
              return
           end if
           ! initialize alpha for use in choosing pivot block size.
           alpha = (one + sqrt(sevten))/eight
           ! compute machine safe minimum
           sfmin = la_dlamch('S')
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 70
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k > 1) then
                 imax = la_izamax(k - 1,a(1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange,
                    ! use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    12 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = imax + la_izamax(k - imax,a(imax,imax + 1),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax > 1) then
                          itemp = la_izamax(imax - 1,a(1,imax),1)
                          dtemp = cabs1(a(itemp,imax))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! cabs1( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 12
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the leading
                    ! submatrix a(1:k,1:k) if we have a 2-by-2 pivot
                    if (p > 1) call la_zswap(p - 1,a(1,k),1,a(1,p),1)
                    if (p < (k - 1)) call la_zswap(k - p - 1,a(p + 1,k),1,a(p,p + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                 end if
                 ! second swap
                 kk = k - kstep + 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the leading
                    ! submatrix a(1:k,1:k)
                    if (kp > 1) call la_zswap(kp - 1,a(1,kk),1,a(1,kp),1)
                    if ((kk > 1) .and. (kp < (kk - 1))) call la_zswap(kk - kp - 1,a(kp + 1,kk), &
                              1,a(kp,kp + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k - 1,k)
                       a(k - 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                 end if
                 ! update the leading submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = u(k)*d(k)
                    ! where u(k) is the k-th column of u
                    if (k > 1) then
                       ! perform a rank-1 update of a(1:k-1,1:k-1) and
                       ! store u(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(1:k-1,1:k-1) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*1/d(k)*w(k)**t
                          d11 = cone/a(k,k)
                          call la_zsyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                          ! store u(k) in column k
                          call la_zscal(k - 1,d11,a(1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = 1,k - 1
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - u(k)*d(k)*u(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_zsyr(uplo,k - 1,-d11,a(1,k),1,a,lda)
                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k-1 now hold
                    ! ( w(k-1) w(k) ) = ( u(k-1) u(k) )*d(k)
                    ! where u(k) and u(k-1) are the k-th and (k-1)-th columns
                    ! of u
                    ! perform a rank-2 update of a(1:k-2,1:k-2) as
                    ! a := a - ( u(k-1) u(k) )*d(k)*( u(k-1) u(k) )**t
                       ! = a - ( ( a(k-1)a(k) )*inv(d(k)) ) * ( a(k-1)a(k) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k > 2) then
                       d12 = a(k - 1,k)
                       d22 = a(k - 1,k - 1)/d12
                       d11 = a(k,k)/d12
                       t = cone/(d11*d22 - cone)
                       do j = k - 2,1,-1
                          wkm1 = t*(d11*a(j,k - 1) - a(j,k))
                          wk = t*(d22*a(j,k) - a(j,k - 1))
                          do i = j,1,-1
                             a(i,j) = a(i,j) - (a(i,k)/d12)*wk - (a(i,k - 1)/d12) &
                                       *wkm1
                          end do
                          ! store u(k) and u(k-1) in cols k and k-1 for row j
                          a(j,k) = wk/d12
                          a(j,k - 1) = wkm1/d12
                       end do
                    end if
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k - 1) = -kp
              end if
              ! decrease k and return to the start of the main loop
              k = k - kstep
              go to 10
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2
              k = 1
              40 continue
              ! if k > n, exit from loop
              if (k > n) go to 70
              kstep = 1
              p = k
              ! determine rows and columns to be interchanged and whether
              ! a 1-by-1 or 2-by-2 pivot block will be used
              absakk = cabs1(a(k,k))
              ! imax is the row-index of the largest off-diagonal element in
              ! column k, and colmax is its absolute value.
              ! determine both colmax and imax.
              if (k < n) then
                 imax = k + la_izamax(n - k,a(k + 1,k),1)
                 colmax = cabs1(a(imax,k))
              else
                 colmax = zero
              end if
              if ((max(absakk,colmax) == zero)) then
                 ! column k is zero or underflow: set info and continue
                 if (info == 0) info = k
                 kp = k
              else
                 ! test for interchange
                 ! equivalent to testing for (used to handle nan and inf)
                 ! absakk>=alpha*colmax
                 if (.not. (absakk < alpha*colmax)) then
                    ! no interchange, use 1-by-1 pivot block
                    kp = k
                 else
                    done = .false.
                    ! loop until pivot found
                    42 continue
                       ! begin pivot search loop body
                       ! jmax is the column-index of the largest off-diagonal
                       ! element in row imax, and rowmax is its absolute value.
                       ! determine both rowmax and jmax.
                       if (imax /= k) then
                          jmax = k - 1 + la_izamax(imax - k,a(imax,k),lda)
                          rowmax = cabs1(a(imax,jmax))
                       else
                          rowmax = zero
                       end if
                       if (imax < n) then
                          itemp = imax + la_izamax(n - imax,a(imax + 1,imax),1)
                          dtemp = cabs1(a(itemp,imax))
                          if (dtemp > rowmax) then
                             rowmax = dtemp
                             jmax = itemp
                          end if
                       end if
                       ! equivalent to testing for (used to handle nan and inf)
                       ! cabs1( a( imax, imax ) )>=alpha*rowmax
                       if (.not. (cabs1(a(imax,imax)) < alpha*rowmax)) then
                          ! interchange rows and columns k and imax,
                          ! use 1-by-1 pivot block
                          kp = imax
                          done = .true.
                       ! equivalent to testing for rowmax == colmax,
                       ! used to handle nan and inf
                       else if ((p == jmax) .or. (rowmax <= colmax)) then
                          ! interchange rows and columns k+1 and imax,
                          ! use 2-by-2 pivot block
                          kp = imax
                          kstep = 2
                          done = .true.
                       else
                          ! pivot not found, set variables and repeat
                          p = imax
                          colmax = rowmax
                          imax = jmax
                       end if
                       ! end pivot search loop body
                    if (.not. done) goto 42
                 end if
                 ! swap two rows and two columns
                 ! first swap
                 if ((kstep == 2) .and. (p /= k)) then
                    ! interchange rows and column k and p in the trailing
                    ! submatrix a(k:n,k:n) if we have a 2-by-2 pivot
                    if (p < n) call la_zswap(n - p,a(p + 1,k),1,a(p + 1,p),1)
                    if (p > (k + 1)) call la_zswap(p - k - 1,a(k + 1,k),1,a(p,k + 1),lda)

                    t = a(k,k)
                    a(k,k) = a(p,p)
                    a(p,p) = t
                 end if
                 ! second swap
                 kk = k + kstep - 1
                 if (kp /= kk) then
                    ! interchange rows and columns kk and kp in the trailing
                    ! submatrix a(k:n,k:n)
                    if (kp < n) call la_zswap(n - kp,a(kp + 1,kk),1,a(kp + 1,kp),1)

                    if ((kk < n) .and. (kp > (kk + 1))) call la_zswap(kp - kk - 1,a(kk + 1,kk), &
                              1,a(kp,kk + 1),lda)
                    t = a(kk,kk)
                    a(kk,kk) = a(kp,kp)
                    a(kp,kp) = t
                    if (kstep == 2) then
                       t = a(k + 1,k)
                       a(k + 1,k) = a(kp,k)
                       a(kp,k) = t
                    end if
                 end if
                 ! update the trailing submatrix
                 if (kstep == 1) then
                    ! 1-by-1 pivot block d(k): column k now holds
                    ! w(k) = l(k)*d(k)
                    ! where l(k) is the k-th column of l
                    if (k < n) then
                    ! perform a rank-1 update of a(k+1:n,k+1:n) and
                    ! store l(k) in column k
                       if (cabs1(a(k,k)) >= sfmin) then
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                          d11 = cone/a(k,k)
                          call la_zsyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                          ! store l(k) in column k
                          call la_zscal(n - k,d11,a(k + 1,k),1)
                       else
                          ! store l(k) in column k
                          d11 = a(k,k)
                          do ii = k + 1,n
                             a(ii,k) = a(ii,k)/d11
                          end do
                          ! perform a rank-1 update of a(k+1:n,k+1:n) as
                          ! a := a - l(k)*d(k)*l(k)**t
                             ! = a - w(k)*(1/d(k))*w(k)**t
                             ! = a - (w(k)/d(k))*(d(k))*(w(k)/d(k))**t
                          call la_zsyr(uplo,n - k,-d11,a(k + 1,k),1,a(k + 1,k + 1),lda)

                       end if
                    end if
                 else
                    ! 2-by-2 pivot block d(k): columns k and k+1 now hold
                    ! ( w(k) w(k+1) ) = ( l(k) l(k+1) )*d(k)
                    ! where l(k) and l(k+1) are the k-th and (k+1)-th columns
                    ! of l
                    ! perform a rank-2 update of a(k+2:n,k+2:n) as
                    ! a := a - ( l(k) l(k+1) ) * d(k) * ( l(k) l(k+1) )**t
                       ! = a - ( ( a(k)a(k+1) )*inv(d(k) ) * ( a(k)a(k+1) )**t
                    ! and store l(k) and l(k+1) in columns k and k+1
                    if (k < n - 1) then
                       d21 = a(k + 1,k)
                       d11 = a(k + 1,k + 1)/d21
                       d22 = a(k,k)/d21
                       t = cone/(d11*d22 - cone)
                       do j = k + 2,n
                          ! compute  d21 * ( w(k)w(k+1) ) * inv(d(k)) for row j
                          wk = t*(d11*a(j,k) - a(j,k + 1))
                          wkp1 = t*(d22*a(j,k + 1) - a(j,k))
                          ! perform a rank-2 update of a(k+2:n,k+2:n)
                          do i = j,n
                             a(i,j) = a(i,j) - (a(i,k)/d21)*wk - (a(i,k + 1)/d21) &
                                       *wkp1
                          end do
                          ! store l(k) and l(k+1) in cols k and k+1 for row j
                          a(j,k) = wk/d21
                          a(j,k + 1) = wkp1/d21
                       end do
                    end if
                 end if
              end if
              ! store details of the interchanges in ipiv
              if (kstep == 1) then
                 ipiv(k) = kp
              else
                 ipiv(k) = -p
                 ipiv(k + 1) = -kp
              end if
              ! increase k and return to the start of the main loop
              k = k + kstep
              go to 40
           end if
           70 continue
           return
     end subroutine la_zsytf2_rook
#ifdef LA_WITH_XDP
