           if (nb > 1 .and. nb < n) then
              iws = ldwork*nb
              if (lwork < iws) then
                 nb = max(lwork/ldwork,1)
                 nbmin = max(2,la_ilaenv(2,'ZSYTRF_RK',uplo,n,-1,-1,-1))
              end if
           else
