                 call la_ylasyf_rook(uplo,n - k + 1,nb,kb,a(k,k),lda,ipiv(k),work, &
                           ldwork,iinfo)
              else
                 ! use unblocked code to factorize columns k:n of a
                 call la_ysytf2_rook(uplo,n - k + 1,a(k,k),lda,ipiv(k),iinfo)
                 kb = n - k + 1
              end if
              ! set info on the first occurrence of a zero pivot
              if (info == 0 .and. iinfo > 0) info = iinfo + k - 1
              ! adjust ipiv
              do j = k,k + kb - 1
                 if (ipiv(j) > 0) then
                    ipiv(j) = ipiv(j) + k - 1
                 else
                    ipiv(j) = ipiv(j) - k + 1
                 end if
              end do
              ! increase k and return to the start of the main loop
              k = k + kb
              go to 20
           end if
           40 continue
           work(1) = lwkopt
           return
     end subroutine la_ysytrf_rook
#endif
#ifdef LA_WITH_QP
     !> WSYTRF_ROOK: computes the factorization of a complex symmetric matrix A
     !> using the bounded Bunch-Kaufman ("rook") diagonal pivoting method.
     !> The form of the factorization is
     !> A = U*D*U**T  or  A = L*D*L**T
     !> where U (or L) is a product of permutation and unit upper (lower)
     !> triangular matrices, and D is symmetric and block diagonal with
     !> 1-by-1 and 2-by-2 diagonal blocks.
     !> This is the blocked version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_wsytrf_rook(uplo,n,a,lda,ipiv,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: lquery,upper
           integer(ilp) :: iinfo,iws,j,k,kb,ldwork,lwkopt,nb,nbmin
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (lwork < 1 .and. .not. lquery) then
              info = -7
           end if
           if (info == 0) then
              ! determine the block size
              nb = la_ilaenv(1,'WSYTRF_ROOK',uplo,n,-1,-1,-1)
              lwkopt = max(1,n*nb)
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('WSYTRF_ROOK',-info)
              return
           else if (lquery) then
              return
           end if
           nbmin = 2
           ldwork = n
           if (nb > 1 .and. nb < n) then
              iws = ldwork*nb
              if (lwork < iws) then
                 nb = max(lwork/ldwork,1)
                 nbmin = max(2,la_ilaenv(2,'WSYTRF_ROOK',uplo,n,-1,-1,-1))
              end if
           else
              iws = 1
           end if
           if (nb < nbmin) nb = n
           if (upper) then
              ! factorize a as u*d*u**t using the upper triangle of a
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! kb, where kb is the number of columns factorized by la_wlasyf_rook;
              ! kb is either nb or nb-1, or k for the last block
              k = n
              10 continue
              ! if k < 1, exit from loop
              if (k < 1) go to 40
              if (k > nb) then
                 ! factorize columns k-kb+1:k of a and use blocked code to
                 ! update columns 1:k-kb
                 call la_wlasyf_rook(uplo,k,nb,kb,a,lda,ipiv,work,ldwork,iinfo)

              else
                 ! use unblocked code to factorize columns 1:k of a
                 call la_wsytf2_rook(uplo,k,a,lda,ipiv,iinfo)
                 kb = k
              end if
              ! set info on the first occurrence of a zero pivot
              if (info == 0 .and. iinfo > 0) info = iinfo
              ! no need to adjust ipiv
              ! decrease k and return to the start of the main loop
              k = k - kb
              go to 10
           else
              ! factorize a as l*d*l**t using the lower triangle of a
              ! k is the main loop index, increasing from 1 to n in steps of
              ! kb, where kb is the number of columns factorized by la_wlasyf_rook;
              ! kb is either nb or nb-1, or n-k+1 for the last block
              k = 1
              20 continue
              ! if k > n, exit from loop
              if (k > n) go to 40
              if (k <= n - nb) then
                 ! factorize columns k:k+kb-1 of a and use blocked code to
                 ! update columns k+kb:n
                 call la_wlasyf_rook(uplo,n - k + 1,nb,kb,a(k,k),lda,ipiv(k),work, &
                           ldwork,iinfo)
              else
                 ! use unblocked code to factorize columns k:n of a
                 call la_wsytf2_rook(uplo,n - k + 1,a(k,k),lda,ipiv(k),iinfo)
                 kb = n - k + 1
              end if
              ! set info on the first occurrence of a zero pivot
              if (info == 0 .and. iinfo > 0) info = iinfo + k - 1
              ! adjust ipiv
              do j = k,k + kb - 1
                 if (ipiv(j) > 0) then
                    ipiv(j) = ipiv(j) + k - 1
                 else
                    ipiv(j) = ipiv(j) - k + 1
                 end if
              end do
              ! increase k and return to the start of the main loop
              k = k + kb
              go to 20
           end if
           40 continue
           work(1) = lwkopt
           return
     end subroutine la_wsytrf_rook
#endif

     !> CSYTRI_ROOK: computes the inverse of a complex symmetric
     !> matrix A using the factorization A = U*D*U**T or A = L*D*L**T
     !> computed by CSYTRF_ROOK.

     pure subroutine la_csytri_rook(uplo,n,a,lda,ipiv,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: k,kp,kstep
           complex(sp) :: ak,akkp1,akp1,d,t,temp
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CSYTRI_ROOK',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              do info = n,1,-1
                 if (ipiv(info) > 0 .and. a(info,info) == czero) return
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              do info = 1,n
                 if (ipiv(info) > 0 .and. a(info,info) == czero) return
              end do
           end if
           info = 0
           if (upper) then
              ! compute inv(a) from the factorization a = u*d*u**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              30 continue
              ! if k > n, exit from loop.
              if (k > n) go to 40
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 a(k,k) = cone/a(k,k)
                 ! compute column k of the inverse.
                 if (k > 1) then
                    call la_ccopy(k - 1,a(1,k),1,work,1)
                    call la_csymv(uplo,k - 1,-cone,a,lda,work,1,czero,a(1,k),1)

                    a(k,k) = a(k,k) - la_cdotu(k - 1,work,1,a(1,k),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = a(k,k + 1)
                 ak = a(k,k)/t
                 akp1 = a(k + 1,k + 1)/t
                 akkp1 = a(k,k + 1)/t
                 d = t*(ak*akp1 - cone)
                 a(k,k) = akp1/d
                 a(k + 1,k + 1) = ak/d
                 a(k,k + 1) = -akkp1/d
                 ! compute columns k and k+1 of the inverse.
                 if (k > 1) then
                    call la_ccopy(k - 1,a(1,k),1,work,1)
                    call la_csymv(uplo,k - 1,-cone,a,lda,work,1,czero,a(1,k),1)

                    a(k,k) = a(k,k) - la_cdotu(k - 1,work,1,a(1,k),1)
                    a(k,k + 1) = a(k,k + 1) - la_cdotu(k - 1,a(1,k),1,a(1,k + 1),1)

                    call la_ccopy(k - 1,a(1,k + 1),1,work,1)
                    call la_csymv(uplo,k - 1,-cone,a,lda,work,1,czero,a(1,k + 1),1)

                    a(k + 1,k + 1) = a(k + 1,k + 1) - la_cdotu(k - 1,work,1,a(1,k + 1),1)

                 end if
                 kstep = 2
              end if
              if (kstep == 1) then
                 ! interchange rows and columns k and ipiv(k) in the leading
                 ! submatrix a(1:k+1,1:k+1)
                 kp = ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_cswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_cswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              else
                 ! interchange rows and columns k and k+1 with -ipiv(k) and
                 ! -ipiv(k+1)in the leading submatrix a(1:k+1,1:k+1)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_cswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_cswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k + 1)
                    a(k,k + 1) = a(kp,k + 1)
                    a(kp,k + 1) = temp
                 end if
                 k = k + 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_cswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_cswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k + 1
              go to 30
              40 continue
           else
              ! compute inv(a) from the factorization a = l*d*l**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              50 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 60
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 a(k,k) = cone/a(k,k)
                 ! compute column k of the inverse.
                 if (k < n) then
                    call la_ccopy(n - k,a(k + 1,k),1,work,1)
                    call la_csymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k),1)
                    a(k,k) = a(k,k) - la_cdotu(n - k,work,1,a(k + 1,k),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = a(k,k - 1)
                 ak = a(k - 1,k - 1)/t
                 akp1 = a(k,k)/t
                 akkp1 = a(k,k - 1)/t
                 d = t*(ak*akp1 - cone)
                 a(k - 1,k - 1) = akp1/d
                 a(k,k) = ak/d
                 a(k,k - 1) = -akkp1/d
                 ! compute columns k-1 and k of the inverse.
                 if (k < n) then
                    call la_ccopy(n - k,a(k + 1,k),1,work,1)
                    call la_csymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k),1)
                    a(k,k) = a(k,k) - la_cdotu(n - k,work,1,a(k + 1,k),1)
                    a(k,k - 1) = a(k,k - 1) - la_cdotu(n - k,a(k + 1,k),1,a(k + 1,k - 1),1 &
                              )
                    call la_ccopy(n - k,a(k + 1,k - 1),1,work,1)
                    call la_csymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k - 1),1)
                    a(k - 1,k - 1) = a(k - 1,k - 1) - la_cdotu(n - k,work,1,a(k + 1,k - 1),1)

                 end if
                 kstep = 2
              end if
              if (kstep == 1) then
                 ! interchange rows and columns k and ipiv(k) in the trailing
                 ! submatrix a(k-1:n,k-1:n)
                 kp = ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_cswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_cswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              else
                 ! interchange rows and columns k and k-1 with -ipiv(k) and
                 ! -ipiv(k-1) in the trailing submatrix a(k-1:n,k-1:n)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_cswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_cswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k - 1)
                    a(k,k - 1) = a(kp,k - 1)
                    a(kp,k - 1) = temp
                 end if
                 k = k - 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_cswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_cswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k - 1
              go to 50
              60 continue
           end if
           return
     end subroutine la_csytri_rook
     !> ZSYTRI_ROOK: computes the inverse of a complex symmetric
     !> matrix A using the factorization A = U*D*U**T or A = L*D*L**T
     !> computed by ZSYTRF_ROOK.

     pure subroutine la_zsytri_rook(uplo,n,a,lda,ipiv,work,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           integer(ilp),intent(in) :: ipiv(*)
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: k,kp,kstep
           complex(dp) :: ak,akkp1,akp1,d,t,temp
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('ZSYTRI_ROOK',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! check that the diagonal matrix d is nonsingular.
           if (upper) then
              ! upper triangular storage: examine d from bottom to top
              do info = n,1,-1
                 if (ipiv(info) > 0 .and. a(info,info) == czero) return
              end do
           else
              ! lower triangular storage: examine d from top to bottom.
              do info = 1,n
                 if (ipiv(info) > 0 .and. a(info,info) == czero) return
              end do
           end if
           info = 0
           if (upper) then
              ! compute inv(a) from the factorization a = u*d*u**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = 1
              30 continue
              ! if k > n, exit from loop.
              if (k > n) go to 40
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 a(k,k) = cone/a(k,k)
                 ! compute column k of the inverse.
                 if (k > 1) then
                    call la_zcopy(k - 1,a(1,k),1,work,1)
                    call la_zsymv(uplo,k - 1,-cone,a,lda,work,1,czero,a(1,k),1)

                    a(k,k) = a(k,k) - la_zdotu(k - 1,work,1,a(1,k),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = a(k,k + 1)
                 ak = a(k,k)/t
                 akp1 = a(k + 1,k + 1)/t
                 akkp1 = a(k,k + 1)/t
                 d = t*(ak*akp1 - cone)
                 a(k,k) = akp1/d
                 a(k + 1,k + 1) = ak/d
                 a(k,k + 1) = -akkp1/d
                 ! compute columns k and k+1 of the inverse.
                 if (k > 1) then
                    call la_zcopy(k - 1,a(1,k),1,work,1)
                    call la_zsymv(uplo,k - 1,-cone,a,lda,work,1,czero,a(1,k),1)

                    a(k,k) = a(k,k) - la_zdotu(k - 1,work,1,a(1,k),1)
                    a(k,k + 1) = a(k,k + 1) - la_zdotu(k - 1,a(1,k),1,a(1,k + 1),1)

                    call la_zcopy(k - 1,a(1,k + 1),1,work,1)
                    call la_zsymv(uplo,k - 1,-cone,a,lda,work,1,czero,a(1,k + 1),1)

                    a(k + 1,k + 1) = a(k + 1,k + 1) - la_zdotu(k - 1,work,1,a(1,k + 1),1)

