                 kp = ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_zswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_zswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              else
                 ! interchange rows and columns k and k+1 with -ipiv(k) and
                 ! -ipiv(k+1)in the leading submatrix a(1:k+1,1:k+1)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_zswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_zswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k + 1)
                    a(k,k + 1) = a(kp,k + 1)
                    a(kp,k + 1) = temp
                 end if
                 k = k + 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp > 1) call la_zswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_zswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k + 1
              go to 30
              40 continue
           else
              ! compute inv(a) from the factorization a = l*d*l**t.
              ! k is the main loop index, increasing from 1 to n in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              50 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 60
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! invert the diagonal block.
                 a(k,k) = cone/a(k,k)
                 ! compute column k of the inverse.
                 if (k < n) then
                    call la_zcopy(n - k,a(k + 1,k),1,work,1)
                    call la_zsymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k),1)
                    a(k,k) = a(k,k) - la_zdotu(n - k,work,1,a(k + 1,k),1)
                 end if
                 kstep = 1
              else
                 ! 2 x 2 diagonal block
                 ! invert the diagonal block.
                 t = a(k,k - 1)
                 ak = a(k - 1,k - 1)/t
                 akp1 = a(k,k)/t
                 akkp1 = a(k,k - 1)/t
                 d = t*(ak*akp1 - cone)
                 a(k - 1,k - 1) = akp1/d
                 a(k,k) = ak/d
                 a(k,k - 1) = -akkp1/d
                 ! compute columns k-1 and k of the inverse.
                 if (k < n) then
                    call la_zcopy(n - k,a(k + 1,k),1,work,1)
                    call la_zsymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k),1)
                    a(k,k) = a(k,k) - la_zdotu(n - k,work,1,a(k + 1,k),1)
                    a(k,k - 1) = a(k,k - 1) - la_zdotu(n - k,a(k + 1,k),1,a(k + 1,k - 1),1 &
                              )
                    call la_zcopy(n - k,a(k + 1,k - 1),1,work,1)
                    call la_zsymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k - 1),1)
                    a(k - 1,k - 1) = a(k - 1,k - 1) - la_zdotu(n - k,work,1,a(k + 1,k - 1),1)

                 end if
                 kstep = 2
              end if
              if (kstep == 1) then
                 ! interchange rows and columns k and ipiv(k) in the trailing
                 ! submatrix a(k-1:n,k-1:n)
                 kp = ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_zswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_zswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              else
                 ! interchange rows and columns k and k-1 with -ipiv(k) and
                 ! -ipiv(k-1) in the trailing submatrix a(k-1:n,k-1:n)
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_zswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_zswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                    temp = a(k,k - 1)
                    a(k,k - 1) = a(kp,k - 1)
                    a(kp,k - 1) = temp
                 end if
                 k = k - 1
                 kp = -ipiv(k)
                 if (kp /= k) then
                    if (kp < n) call la_zswap(n - kp,a(kp + 1,k),1,a(kp + 1,kp),1)
                    call la_zswap(kp - k - 1,a(k + 1,k),1,a(kp,k + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
                    a(kp,kp) = temp
                 end if
              end if
              k = k - 1
              go to 50
              60 continue
           end if
           return
