                    if (kp > 1) call la_yswap(kp - 1,a(1,k),1,a(1,kp),1)
                    call la_yswap(k - kp - 1,a(kp + 1,k),1,a(kp,kp + 1),lda)
                    temp = a(k,k)
                    a(k,k) = a(kp,kp)
