                    a(k,k - 1) = a(k,k - 1) - la_ydotu(n - k,a(k + 1,k),1,a(k + 1,k - 1),1 &
                              )
                    call la_ycopy(n - k,a(k + 1,k - 1),1,work,1)
                    call la_ysymv(uplo,n - k,-cone,a(k + 1,k + 1),lda,work,1,czero,a(k + 1, &
                               k - 1),1)
