                 ! stored in columns k and k+1 of a.
                 if (k < n - 1) then
                    call la_cgeru(n - k - 1,nrhs,-cone,a(k + 2,k),1,b(k,1),ldb,b(k + 2, &
                              1),ldb)
                    call la_cgeru(n - k - 1,nrhs,-cone,a(k + 2,k + 1),1,b(k + 1,1),ldb,b(k + &
                              2,1),ldb)
                 end if
                 ! multiply by the inverse of the diagonal block.
                 akm1k = a(k + 1,k)
                 akm1 = a(k,k)/akm1k
                 ak = a(k + 1,k + 1)/akm1k
                 denom = akm1*ak - cone
                 do j = 1,nrhs
                    bkm1 = b(k,j)/akm1k
                    bk = b(k + 1,j)/akm1k
                    b(k,j) = (ak*bkm1 - bk)/denom
                    b(k + 1,j) = (akm1*bk - bkm1)/denom
                 end do
                 k = k + 2
              end if
              go to 60
              80 continue
              ! next solve l**t *x = b, overwriting b with x.
              ! k is the main loop index, decreasing from n to 1 in steps of
              ! 1 or 2, depending on the size of the diagonal blocks.
              k = n
              90 continue
              ! if k < 1, exit from loop.
              if (k < 1) go to 100
              if (ipiv(k) > 0) then
                 ! 1 x 1 diagonal block
                 ! multiply by inv(l**t(k)), where l(k) is the transformation
                 ! stored in column k of a.
                 if (k < n) call la_cgemv('TRANSPOSE',n - k,nrhs,-cone,b(k + 1,1),ldb,a(k + &
                           1,k),1,cone,b(k,1),ldb)
                 ! interchange rows k and ipiv(k).
                 kp = ipiv(k)
                 if (kp /= k) call la_cswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 k = k - 1
              else
                 ! 2 x 2 diagonal block
                 ! multiply by inv(l**t(k-1)), where l(k-1) is the transformation
                 ! stored in columns k-1 and k of a.
                 if (k < n) then
                    call la_cgemv('TRANSPOSE',n - k,nrhs,-cone,b(k + 1,1),ldb,a(k + 1,k) &
                              ,1,cone,b(k,1),ldb)
                    call la_cgemv('TRANSPOSE',n - k,nrhs,-cone,b(k + 1,1),ldb,a(k + 1,k - &
                              1),1,cone,b(k - 1,1),ldb)
                 end if
                 ! interchange rows k and -ipiv(k) then k-1 and -ipiv(k-1)
                 kp = -ipiv(k)
                 if (kp /= k) call la_cswap(nrhs,b(k,1),ldb,b(kp,1),ldb)
                 kp = -ipiv(k - 1)
                 if (kp /= k - 1) call la_cswap(nrhs,b(k - 1,1),ldb,b(kp,1),ldb)
                 k = k - 2
              end if
              go to 90
              100 continue
           end if
           return
     end subroutine la_csytrs_rook
