                 alpha = -a(j,k - 1)
                 call la_zaxpy(mj,alpha,a(j,k - 2),1,work(1),1)
              end if
              ! set a(j, j) = t(j, j)
              a(j,k) = work(1)
              if (j < m) then
                 ! compute work(2:m) = t(j, j) l((j+1):m, j)
                  ! where a(j, j) = t(j, j) and a((j+1):m, j-1) = l((j+1):m, j)
                 if (k > 1) then
                    alpha = -a(j,k)
                    call la_zaxpy(m - j,alpha,a(j + 1,k - 1),1,work(2),1)
                 end if
                 ! find max(|work(2:m)|)
                 i2 = la_izamax(m - j,work(2),1) + 1
                 piv = work(i2)
                 ! apply symmetric pivot
                 if ((i2 /= 2) .and. (piv /= 0)) then
