                    ! swap a(i2+1:m, i1) with a(i2+1:m, i2)
                    if (i2 < m) call la_zswap(m - i2,a(i2 + 1,j1 + i1 - 1),1,a(i2 + 1,j1 + i2 - 1), &
                              1)
