                    call la_zswap(i1 - 1,h(i1,1),ldh,h(i2,1),ldh)
                    ipiv(i1) = i2
                    if (i1 > (k1 - 1)) then
                       ! swap l(1:i1-1, i1) with l(1:i1-1, i2),
                        ! skipping the first column
