                    end if
                 else
                    ipiv(j + 1) = j + 1
                 end if
                 ! set a(j+1, j) = t(j+1, j)
                 a(j + 1,k) = work(2)
                 if (j < nb) then
                    ! copy a(j+1:m, j+1) into h(j+1:m, j),
                    call la_zcopy(m - j,a(j + 1,k + 1),1,h(j + 1,j + 1),1)
                 end if
