        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: m,nb,j1,lda,ldh
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(qp),intent(inout) :: a(lda,*),h(ldh,*)
           complex(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: j,k,k1,i1,i2,mj
           complex(qp) :: piv,alpha
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           j = 1
           ! k1 is the first column of the panel to be factorized
           ! i.e.,  k1 is 2 for the first block column, and 1 for the rest of the blocks
           k1 = (2 - j1) + 1
           if (la_lsame(uplo,'U')) then
              ! .....................................................
              ! factorize a as u**t*d*u using the upper triangle of a
              ! .....................................................
              10 continue
              if (j > min(m,nb)) go to 20
              ! k is the column to be factorized
               ! when being called from la_wsytrf_aa,
               ! > for the first block column, j1 is 1, hence j1+j-1 is j,
               ! > for the rest of the columns, j1 is 2, and j1+j-1 is j+1,
              k = j1 + j - 1
              if (j == m) then
                  ! only need to compute t(j, j)
                  mj = 1
              else
                  mj = m - j + 1
              end if
              ! h(j:m, j) := a(j, j:m) - h(j:m, 1:(j-1)) * l(j1:(j-1), j),
               ! where h(j:m, j) has been initialized to be a(j, j:m)
              if (k > 2) then
              ! k is the column to be factorized
               ! > for the first block column, k is j, skipping the first two
                 ! columns
               ! > for the rest of the columns, k is j+1, skipping only the
                 ! first column
                 call la_wgemv('NO TRANSPOSE',mj,j - k1,-cone,h(j,k1),ldh,a(1,j),1, &
                           cone,h(j,j),1)
              end if
              ! copy h(i:m, i) into work
              call la_wcopy(mj,h(j,j),1,work(1),1)
              if (j > k1) then
                 ! compute work := work - l(j-1, j:m) * t(j-1,j),
                  ! where a(j-1, j) stores t(j-1, j) and a(j-2, j:m) stores u(j-1, j:m)
                 alpha = -a(k - 1,j)
                 call la_waxpy(mj,alpha,a(k - 2,j),lda,work(1),1)
              end if
              ! set a(j, j) = t(j, j)
              a(k,j) = work(1)
              if (j < m) then
                 ! compute work(2:m) = t(j, j) l(j, (j+1):m)
                  ! where a(j, j) stores t(j, j) and a(j-1, (j+1):m) stores u(j, (j+1):m)
                 if (k > 1) then
                    alpha = -a(k,j)
                    call la_waxpy(m - j,alpha,a(k - 1,j + 1),lda,work(2),1)
                 end if
                 ! find max(|work(2:m)|)
                 i2 = la_iwamax(m - j,work(2),1) + 1
                 piv = work(i2)
                 ! apply symmetric pivot
                 if ((i2 /= 2) .and. (piv /= 0)) then
                    ! swap work(i1) and work(i2)
                    i1 = 2
                    work(i2) = work(i1)
                    work(i1) = piv
                    ! swap a(i1, i1+1:m) with a(i1+1:m, i2)
                    i1 = i1 + j - 1
                    i2 = i2 + j - 1
                    call la_wswap(i2 - i1 - 1,a(j1 + i1 - 1,i1 + 1),lda,a(j1 + i1,i2),1)

                    ! swap a(i1, i2+1:m) with a(i2, i2+1:m)
                    if (i2 < m) call la_wswap(m - i2,a(j1 + i1 - 1,i2 + 1),lda,a(j1 + i2 - 1,i2 + 1), &
                               lda)
                    ! swap a(i1, i1) with a(i2,i2)
                    piv = a(i1 + j1 - 1,i1)
                    a(j1 + i1 - 1,i1) = a(j1 + i2 - 1,i2)
                    a(j1 + i2 - 1,i2) = piv
                    ! swap h(i1, 1:j1) with h(i2, 1:j1)
                    call la_wswap(i1 - 1,h(i1,1),ldh,h(i2,1),ldh)
                    ipiv(i1) = i2
                    if (i1 > (k1 - 1)) then
                       ! swap l(1:i1-1, i1) with l(1:i1-1, i2),
                        ! skipping the first column
                       call la_wswap(i1 - k1 + 1,a(1,i1),1,a(1,i2),1)
                    end if
                 else
                    ipiv(j + 1) = j + 1
                 end if
                 ! set a(j, j+1) = t(j, j+1)
                 a(k,j + 1) = work(2)
                 if (j < nb) then
                    ! copy a(j+1:m, j+1) into h(j:m, j),
                    call la_wcopy(m - j,a(k + 1,j + 1),lda,h(j + 1,j + 1),1)
                 end if
                 ! compute l(j+2, j+1) = work( 3:m ) / t(j, j+1),
                  ! where a(j, j+1) = t(j, j+1) and a(j+2:m, j) = l(j+2:m, j+1)
                 if (j < (m - 1)) then
                    if (a(k,j + 1) /= czero) then
                       alpha = cone/a(k,j + 1)
                       call la_wcopy(m - j - 1,work(3),1,a(k,j + 2),lda)
                       call la_wscal(m - j - 1,alpha,a(k,j + 2),lda)
                    else
                       call la_wlaset('FULL',1,m - j - 1,czero,czero,a(k,j + 2),lda)

                    end if
                 end if
              end if
              j = j + 1
              go to 10
              20 continue
           else
              ! .....................................................
              ! factorize a as l*d*l**t using the lower triangle of a
              ! .....................................................
              30 continue
              if (j > min(m,nb)) go to 40
              ! k is the column to be factorized
               ! when being called from la_wsytrf_aa,
               ! > for the first block column, j1 is 1, hence j1+j-1 is j,
               ! > for the rest of the columns, j1 is 2, and j1+j-1 is j+1,
              k = j1 + j - 1
              if (j == m) then
                  ! only need to compute t(j, j)
                  mj = 1
              else
                  mj = m - j + 1
              end if
              ! h(j:m, j) := a(j:m, j) - h(j:m, 1:(j-1)) * l(j, j1:(j-1))^t,
               ! where h(j:m, j) has been initialized to be a(j:m, j)
              if (k > 2) then
              ! k is the column to be factorized
               ! > for the first block column, k is j, skipping the first two
                 ! columns
               ! > for the rest of the columns, k is j+1, skipping only the
                 ! first column
                 call la_wgemv('NO TRANSPOSE',mj,j - k1,-cone,h(j,k1),ldh,a(j,1), &
                           lda,cone,h(j,j),1)
              end if
              ! copy h(j:m, j) into work
              call la_wcopy(mj,h(j,j),1,work(1),1)
              if (j > k1) then
                 ! compute work := work - l(j:m, j-1) * t(j-1,j),
                  ! where a(j-1, j) = t(j-1, j) and a(j, j-2) = l(j, j-1)
                 alpha = -a(j,k - 1)
                 call la_waxpy(mj,alpha,a(j,k - 2),1,work(1),1)
              end if
              ! set a(j, j) = t(j, j)
              a(j,k) = work(1)
              if (j < m) then
                 ! compute work(2:m) = t(j, j) l((j+1):m, j)
                  ! where a(j, j) = t(j, j) and a((j+1):m, j-1) = l((j+1):m, j)
                 if (k > 1) then
                    alpha = -a(j,k)
                    call la_waxpy(m - j,alpha,a(j + 1,k - 1),1,work(2),1)
                 end if
                 ! find max(|work(2:m)|)
                 i2 = la_iwamax(m - j,work(2),1) + 1
                 piv = work(i2)
                 ! apply symmetric pivot
                 if ((i2 /= 2) .and. (piv /= 0)) then
                    ! swap work(i1) and work(i2)
                    i1 = 2
                    work(i2) = work(i1)
                    work(i1) = piv
                    ! swap a(i1+1:m, i1) with a(i2, i1+1:m)
                    i1 = i1 + j - 1
                    i2 = i2 + j - 1
                    call la_wswap(i2 - i1 - 1,a(i1 + 1,j1 + i1 - 1),1,a(i2,j1 + i1),lda)

                    ! swap a(i2+1:m, i1) with a(i2+1:m, i2)
                    if (i2 < m) call la_wswap(m - i2,a(i2 + 1,j1 + i1 - 1),1,a(i2 + 1,j1 + i2 - 1), &
                              1)
                    ! swap a(i1, i1) with a(i2, i2)
                    piv = a(i1,j1 + i1 - 1)
                    a(i1,j1 + i1 - 1) = a(i2,j1 + i2 - 1)
                    a(i2,j1 + i2 - 1) = piv
                    ! swap h(i1, i1:j1) with h(i2, i2:j1)
                    call la_wswap(i1 - 1,h(i1,1),ldh,h(i2,1),ldh)
                    ipiv(i1) = i2
                    if (i1 > (k1 - 1)) then
                       ! swap l(1:i1-1, i1) with l(1:i1-1, i2),
                        ! skipping the first column
                       call la_wswap(i1 - k1 + 1,a(i1,1),lda,a(i2,1),lda)
                    end if
                 else
                    ipiv(j + 1) = j + 1
                 end if
                 ! set a(j+1, j) = t(j+1, j)
                 a(j + 1,k) = work(2)
                 if (j < nb) then
                    ! copy a(j+1:m, j+1) into h(j+1:m, j),
                    call la_wcopy(m - j,a(j + 1,k + 1),1,h(j + 1,j + 1),1)
                 end if
                 ! compute l(j+2, j+1) = work( 3:m ) / t(j, j+1),
                  ! where a(j, j+1) = t(j, j+1) and a(j+2:m, j) = l(j+2:m, j+1)
                 if (j < (m - 1)) then
                    if (a(j + 1,k) /= czero) then
                       alpha = cone/a(j + 1,k)
                       call la_wcopy(m - j - 1,work(3),1,a(j + 2,k),1)
                       call la_wscal(m - j - 1,alpha,a(j + 2,k),1)
                    else
                       call la_wlaset('FULL',m - j - 1,1,czero,czero,a(j + 2,k),lda)

                    end if
                 end if
              end if
              j = j + 1
              go to 30
              40 continue
           end if
           return
     end subroutine la_wlasyf_aa
#endif

     !> CSYTRF_AA: computes the factorization of a complex symmetric matrix A
     !> using the Aasen's algorithm.  The form of the factorization is
     !> A = U**T*T*U  or  A = L*T*L**T
     !> where U (or L) is a product of permutation and unit upper (lower)
     !> triangular matrices, and T is a complex symmetric tridiagonal matrix.
     !> This is the blocked version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_csytrf_aa(uplo,n,a,lda,ipiv,work,lwork,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: n,lda,lwork
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper
           integer(ilp) :: j,lwkopt
           integer(ilp) :: nb,mj,nj,k1,k2,j1,j2,j3,jb
           complex(sp) :: alpha
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! determine the block size
           nb = la_ilaenv(1,'CSYTRF_AA',uplo,n,-1,-1,-1)
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (lwork < max(1,2*n) .and. .not. lquery) then
              info = -7
           end if
           if (info == 0) then
              lwkopt = (nb + 1)*n
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('CSYTRF_AA',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return
           if (n == 0) then
               return
           end if
           ipiv(1) = 1
           if (n == 1) then
              return
           end if
           ! adjust block size based on the workspace size
           if (lwork < ((1 + nb)*n)) then
              nb = (lwork - n)/n
           end if
           if (upper) then
              ! .....................................................
              ! factorize a as u**t*d*u using the upper triangle of a
              ! .....................................................
              ! copy first row a(1, 1:n) into h(1:n) (stored in work(1:n))
              call la_ccopy(n,a(1,1),lda,work(1),1)
              ! j is the main loop index, increasing from 1 to n in steps of
              ! jb, where jb is the number of columns factorized by la_clasyf;
              ! jb is either nb, or n-j+1 for the last block
              j = 0
              10 continue
              if (j >= n) go to 20
              ! each step of the main loop
               ! j is the last column of the previous panel
               ! j1 is the first column of the current panel
               ! k1 identifies if the previous column of the panel has been
                ! explicitly stored, e.g., k1=1 for the first panel, and
                ! k1=0 for the rest
              j1 = j + 1
              jb = min(n - j1 + 1,nb)
              k1 = max(1,j) - j
              ! panel factorization
              call la_clasyf_aa(uplo,2 - k1,n - j,jb,a(max(1,j),j + 1),lda,ipiv(j + 1), &
                        work,n,work(n*nb + 1))
              ! adjust ipiv and apply it back (j-th step picks (j+1)-th pivot)
              do j2 = j + 2,min(n,j + jb + 1)
                 ipiv(j2) = ipiv(j2) + j
                 if ((j2 /= ipiv(j2)) .and. ((j1 - k1) > 2)) then
                    call la_cswap(j1 - k1 - 2,a(1,j2),1,a(1,ipiv(j2)),1)
                 end if
              end do
              j = j + jb
              ! trailing submatrix update, where
               ! the row a(j1-1, j2-1:n) stores u(j1, j2+1:n) and
               ! work stores the current block of the auxiriarly matrix h
              if (j < n) then
                 ! if first panel and jb=1 (nb=1), then nothing to do
                 if (j1 > 1 .or. jb > 1) then
                    ! merge rank-1 update with blas-3 update
                    alpha = a(j,j + 1)
                    a(j,j + 1) = cone
                    call la_ccopy(n - j,a(j - 1,j + 1),lda,work((j + 1 - j1 + 1) + jb*n),1)

                    call la_cscal(n - j,alpha,work((j + 1 - j1 + 1) + jb*n),1)
                    ! k1 identifies if the previous column of the panel has been
                     ! explicitly stored, e.g., k1=1 and k2= 0 for the first panel,
                     ! while k1=0 and k2=1 for the rest
                    if (j1 > 1) then
                       ! not first panel
                       k2 = 1
                    else
                       ! first panel
                       k2 = 0
                       ! first update skips the first column
                       jb = jb - 1
                    end if
                    do j2 = j + 1,n,nb
                       nj = min(nb,n - j2 + 1)
                       ! update (j2, j2) diagonal block with la_cgemv
                       j3 = j2
                       do mj = nj - 1,1,-1
                          call la_cgemv('NO TRANSPOSE',mj,jb + 1,-cone,work(j3 - j1 + 1 + k1*n), &
                                     n,a(j1 - k2,j3),1,cone,a(j3,j3),lda)
                          j3 = j3 + 1
                       end do
                       ! update off-diagonal block of j2-th block row with la_cgemm
                       call la_cgemm('TRANSPOSE','TRANSPOSE',nj,n - j3 + 1,jb + 1,-cone,a(j1 - &
                                 k2,j2),lda,work(j3 - j1 + 1 + k1*n),n,cone,a(j2,j3),lda)
                    end do
                    ! recover t( j, j+1 )
                    a(j,j + 1) = alpha
                 end if
                 ! work(j+1, 1) stores h(j+1, 1)
                 call la_ccopy(n - j,a(j + 1,j + 1),lda,work(1),1)
              end if
              go to 10
           else
              ! .....................................................
              ! factorize a as l*d*l**t using the lower triangle of a
              ! .....................................................
              ! copy first column a(1:n, 1) into h(1:n, 1)
               ! (stored in work(1:n))
              call la_ccopy(n,a(1,1),1,work(1),1)
              ! j is the main loop index, increasing from 1 to n in steps of
              ! jb, where jb is the number of columns factorized by la_clasyf;
              ! jb is either nb, or n-j+1 for the last block
              j = 0
              11 continue
              if (j >= n) go to 20
              ! each step of the main loop
               ! j is the last column of the previous panel
               ! j1 is the first column of the current panel
               ! k1 identifies if the previous column of the panel has been
                ! explicitly stored, e.g., k1=1 for the first panel, and
                ! k1=0 for the rest
              j1 = j + 1
              jb = min(n - j1 + 1,nb)
              k1 = max(1,j) - j
              ! panel factorization
              call la_clasyf_aa(uplo,2 - k1,n - j,jb,a(j + 1,max(1,j)),lda,ipiv(j + 1), &
                        work,n,work(n*nb + 1))
              ! adjust ipiv and apply it back (j-th step picks (j+1)-th pivot)
              do j2 = j + 2,min(n,j + jb + 1)
                 ipiv(j2) = ipiv(j2) + j
                 if ((j2 /= ipiv(j2)) .and. ((j1 - k1) > 2)) then
                    call la_cswap(j1 - k1 - 2,a(j2,1),lda,a(ipiv(j2),1),lda)
                 end if
              end do
              j = j + jb
              ! trailing submatrix update, where
                ! a(j2+1, j1-1) stores l(j2+1, j1) and
                ! work(j2+1, 1) stores h(j2+1, 1)
              if (j < n) then
                 ! if first panel and jb=1 (nb=1), then nothing to do
                 if (j1 > 1 .or. jb > 1) then
                    ! merge rank-1 update with blas-3 update
                    alpha = a(j + 1,j)
                    a(j + 1,j) = cone
                    call la_ccopy(n - j,a(j + 1,j - 1),1,work((j + 1 - j1 + 1) + jb*n),1)
                    call la_cscal(n - j,alpha,work((j + 1 - j1 + 1) + jb*n),1)
                    ! k1 identifies if the previous column of the panel has been
                     ! explicitly stored, e.g., k1=1 and k2= 0 for the first panel,
                     ! while k1=0 and k2=1 for the rest
                    if (j1 > 1) then
                       ! not first panel
                       k2 = 1
                    else
                       ! first panel
                       k2 = 0
                       ! first update skips the first column
                       jb = jb - 1
                    end if
                    do j2 = j + 1,n,nb
                       nj = min(nb,n - j2 + 1)
                       ! update (j2, j2) diagonal block with la_cgemv
                       j3 = j2
                       do mj = nj - 1,1,-1
                          call la_cgemv('NO TRANSPOSE',mj,jb + 1,-cone,work(j3 - j1 + 1 + k1*n), &
                                     n,a(j3,j1 - k2),lda,cone,a(j3,j3),1)
                          j3 = j3 + 1
                       end do
                       ! update off-diagonal block in j2-th block column with la_cgemm
                       call la_cgemm('NO TRANSPOSE','TRANSPOSE',n - j3 + 1,nj,jb + 1,-cone, &
                       work(j3 - j1 + 1 + k1*n),n,a(j2,j1 - k2),lda,cone,a(j3,j2),lda)

                    end do
                    ! recover t( j+1, j )
                    a(j + 1,j) = alpha
                 end if
                 ! work(j+1, 1) stores h(j+1, 1)
                 call la_ccopy(n - j,a(j + 1,j + 1),1,work(1),1)
              end if
              go to 11
           end if
           20 continue
           work(1) = lwkopt
           return
     end subroutine la_csytrf_aa
     !> ZSYTRF_AA: computes the factorization of a complex symmetric matrix A
     !> using the Aasen's algorithm.  The form of the factorization is
     !> A = U**T*T*U  or  A = L*T*L**T
     !> where U (or L) is a product of permutation and unit upper (lower)
     !> triangular matrices, and T is a complex symmetric tridiagonal matrix.
     !> This is the blocked version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_zsytrf_aa(uplo,n,a,lda,ipiv,work,lwork,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: n,lda,lwork
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(out) :: ipiv(*)
           complex(dp),intent(inout) :: a(lda,*)
           complex(dp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper
           integer(ilp) :: j,lwkopt
           integer(ilp) :: nb,mj,nj,k1,k2,j1,j2,j3,jb
           complex(dp) :: alpha
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! determine the block size
           nb = la_ilaenv(1,'ZSYTRF_AA',uplo,n,-1,-1,-1)
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (lwork < max(1,2*n) .and. .not. lquery) then
              info = -7
           end if
           if (info == 0) then
              lwkopt = (nb + 1)*n
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('ZSYTRF_AA',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return
           if (n == 0) then
               return
           end if
           ipiv(1) = 1
           if (n == 1) then
              return
           end if
           ! adjust block size based on the workspace size
           if (lwork < ((1 + nb)*n)) then
              nb = (lwork - n)/n
           end if
           if (upper) then
              ! .....................................................
              ! factorize a as u**t*d*u using the upper triangle of a
              ! .....................................................
              ! copy first row a(1, 1:n) into h(1:n) (stored in work(1:n))
              call la_zcopy(n,a(1,1),lda,work(1),1)
              ! j is the main loop index, increasing from 1 to n in steps of
              ! jb, where jb is the number of columns factorized by la_zlasyf;
              ! jb is either nb, or n-j+1 for the last block
              j = 0
              10 continue
              if (j >= n) go to 20
              ! each step of the main loop
               ! j is the last column of the previous panel
               ! j1 is the first column of the current panel
               ! k1 identifies if the previous column of the panel has been
                ! explicitly stored, e.g., k1=1 for the first panel, and
                ! k1=0 for the rest
              j1 = j + 1
              jb = min(n - j1 + 1,nb)
              k1 = max(1,j) - j
              ! panel factorization
              call la_zlasyf_aa(uplo,2 - k1,n - j,jb,a(max(1,j),j + 1),lda,ipiv(j + 1), &
                        work,n,work(n*nb + 1))
              ! adjust ipiv and apply it back (j-th step picks (j+1)-th pivot)
              do j2 = j + 2,min(n,j + jb + 1)
                 ipiv(j2) = ipiv(j2) + j
                 if ((j2 /= ipiv(j2)) .and. ((j1 - k1) > 2)) then
                    call la_zswap(j1 - k1 - 2,a(1,j2),1,a(1,ipiv(j2)),1)
                 end if
              end do
              j = j + jb
              ! trailing submatrix update, where
               ! the row a(j1-1, j2-1:n) stores u(j1, j2+1:n) and
               ! work stores the current block of the auxiriarly matrix h
              if (j < n) then
                 ! if first panel and jb=1 (nb=1), then nothing to do
                 if (j1 > 1 .or. jb > 1) then
                    ! merge rank-1 update with blas-3 update
                    alpha = a(j,j + 1)
                    a(j,j + 1) = cone
                    call la_zcopy(n - j,a(j - 1,j + 1),lda,work((j + 1 - j1 + 1) + jb*n),1)

