                       do mj = nj - 1,1,-1
                          call la_zgemv('NO TRANSPOSE',mj,jb + 1,-cone,work(j3 - j1 + 1 + k1*n), &
                                     n,a(j1 - k2,j3),1,cone,a(j3,j3),lda)
                          j3 = j3 + 1
                       end do
                       ! update off-diagonal block of j2-th block row with la_zgemm
                       call la_zgemm('TRANSPOSE','TRANSPOSE',nj,n - j3 + 1,jb + 1,-cone,a(j1 - &
                                 k2,j2),lda,work(j3 - j1 + 1 + k1*n),n,cone,a(j2,j3),lda)
                    end do
