                        work,n,work(n*nb + 1))
              ! adjust ipiv and apply it back (j-th step picks (j+1)-th pivot)
              do j2 = j + 2,min(n,j + jb + 1)
                 ipiv(j2) = ipiv(j2) + j
                 if ((j2 /= ipiv(j2)) .and. ((j1 - k1) > 2)) then
                    call la_zswap(j1 - k1 - 2,a(j2,1),lda,a(ipiv(j2),1),lda)
                 end if
              end do
              j = j + jb
              ! trailing submatrix update, where
                ! a(j2+1, j1-1) stores l(j2+1, j1) and
                ! work(j2+1, 1) stores h(j2+1, 1)
              if (j < n) then
                 ! if first panel and jb=1 (nb=1), then nothing to do
                 if (j1 > 1 .or. jb > 1) then
                    ! merge rank-1 update with blas-3 update
                    alpha = a(j + 1,j)
                    a(j + 1,j) = cone
                    call la_zcopy(n - j,a(j + 1,j - 1),1,work((j + 1 - j1 + 1) + jb*n),1)
                    call la_zscal(n - j,alpha,work((j + 1 - j1 + 1) + jb*n),1)
                    ! k1 identifies if the previous column of the panel has been
                     ! explicitly stored, e.g., k1=1 and k2= 0 for the first panel,
                     ! while k1=0 and k2=1 for the rest
                    if (j1 > 1) then
                       ! not first panel
                       k2 = 1
                    else
                       ! first panel
                       k2 = 0
                       ! first update skips the first column
                       jb = jb - 1
                    end if
                    do j2 = j + 1,n,nb
                       nj = min(nb,n - j2 + 1)
                       ! update (j2, j2) diagonal block with la_zgemv
                       j3 = j2
                       do mj = nj - 1,1,-1
                          call la_zgemv('NO TRANSPOSE',mj,jb + 1,-cone,work(j3 - j1 + 1 + k1*n), &
                                     n,a(j3,j1 - k2),lda,cone,a(j3,j3),1)
                          j3 = j3 + 1
                       end do
                       ! update off-diagonal block in j2-th block column with la_zgemm
                       call la_zgemm('NO TRANSPOSE','TRANSPOSE',n - j3 + 1,nj,jb + 1,-cone, &
                       work(j3 - j1 + 1 + k1*n),n,a(j2,j1 - k2),lda,cone,a(j3,j2),lda)

                    end do
                    ! recover t( j+1, j )
                    a(j + 1,j) = alpha
                 end if
                 ! work(j+1, 1) stores h(j+1, 1)
                 call la_zcopy(n - j,a(j + 1,j + 1),1,work(1),1)
              end if
              go to 11
           end if
           20 continue
           work(1) = lwkopt
           return
     end subroutine la_zsytrf_aa
